/* 原创伴读：第10—15章。静态内容与示例；网页不执行 R。 */
(() => {
  const S = (title, body) => ({ title, body });
  const L = (id, title, tags, objective, prereq, sections, question, steps, answer, mistakes, q, options, correct, explanation, takeaway, extra = {}) => ({
    id: 'prob-' + id, title, minutes: 24, level: '进阶', tags, objective, prereq, sections,
    example: { question, steps, answer }, mistakes,
    quiz: { question: q, options, answer: correct, explanation }, takeaway, ...extra
  });
  const C = (id, order, title, sections, lessons) => ({ id: 'prob-' + id, order, title,
    sections: sections.map(([code, name, ids]) => ({ code, title: name, lessonIds: ids.map(id => 'prob-' + id) })), lessons });
  const R = (source, explanation, texts) => ({ language: 'R 示例（需在 R 中运行）', source, explanation,
    lines: texts.map((text, i) => ({ line: i + 1, text })) });
  const chapters = [];
  chapters.push(C('bootstrap', 10, 'bootstrap方法（自助法）', [
    ['10.1', '非参数bootstrap方法', ['bootstrap-world', 'bootstrap-interval']],
    ['10.2', '参数bootstrap方法', ['bootstrap-parametric']],
    ['10.3', 'bootstrap假设检验方法举例', ['bootstrap-null', 'bootstrap-limits']]
  ], [
    L('bootstrap-world', '只有一份样本，怎样想象重复抽样？', ['bootstrap','经验分布','有放回抽样'], '把“重抽样”与“增加真实数据”分开，亲手列出小样本的自助世界。', '样本、统计量、抽样分布、独立同分布', [
      S('先承认我们缺少的是什么', '你称了三包零食，重量是2、4、6，平均数是4。现在关心的不是再算一次4，而是“若重新买三包，平均数通常能晃动多大”。这问的是统计量的抽样分布。理想方法是回到真实总体，独立地重复采三包，但现实往往只有眼前这一份数据。bootstrap的想法是先搭一个便宜的替身世界：把观测到的2、4、6各看成占三分之一的总体，然后在这个替身总体中重复抽样。它给的是依赖当前样本的近似，不会凭空知道从未观察到的尾部。'),
      S('星号不是乘法，是“替身世界”标签', '经验分布Fₙ给每个观测位置质量1/n。给定原样本，从Fₙ独立有放回抽n次，得到X₁*到Xₙ*；同一个位置可以被抽中多次。对它使用与原来完全相同的算法，算出θ̂*=T(X₁*,…,Xₙ*)。做B次就得到B个统计量。星号表示“在自助世界中生成”，不是原总体又贡献了B份证据。固定原数据后，变动来自电脑的重抽样；换一份原数据，整个替身世界又会改变。这两层随机性分清后，许多看似绕口的定义就变成了两次拍摄。'),
      S('为什么必须有放回，而且通常抽n个', '不放回地把原来n个数全部抽走，只会改变排列；平均数等对顺序不敏感的统计量始终一样，根本看不到抽样波动。有放回使每次样本中各观测的次数变化，才形成替身分布。通常仍抽n个，是因为我们正在模拟“样本量为n的统计量”，而不是另一个更大样本量的问题。三包例子一共有3³=27个等可能的有序自助样本；(2,2,6)可以，(6,6,6)也可以。不同排列各自计数，因为原始抽样的三个位置有先后，不能把组合错误地设成等可能。'),
      S('做题时先画出两层，再讨论误差', '读到自助法先写三项：原样本是什么、目标统计量是什么、替身总体是什么。再问独立同分布是否合理：不同家庭的一次测量与同一人连续三天的测量，依赖结构并不相同。普通逐个重抽样会破坏时间关联，不能直接照用。对于一般光滑统计量，在合适正则条件和足够样本下，经验分布能够提供有用近似；这不是“任何统计量都一定有效”的定理。B增大主要减少电脑模拟的误差，n增大才可能增加关于真实总体的信息。两种“更多”解决的是不同短板。')
    ], '对样本(2,4,6)，列出一个自助样本并计算其均值；B很大能否等价于得到新数据？', ['把替身总体写为：2、4、6各以1/3概率抽到。','有放回抽三次，例如得到(2,2,6)。','对同一统计量取均值，得到10/3。','重复所得均值形成给定原样本的自助分布；原始独立观测仍只有三个。'], '这次均值为10/3；B再大也不把三份真实观测变成更多真实观测。', ['把“抽取不同数值”当作重抽样；实际上抽的是观测位置，重复值仍可来自不同位置。','以为无放回抽完整份数据也能估计均值波动；此时均值恒定。'], '原样本量为n，普通非参数bootstrap每次通常怎样抽？', ['从原样本位置有放回抽n次','不放回取走全部n个再随机排列','只抽一次后把数字复制n份','从所有实数上均匀抽n次'], 0, '经验分布提供每个观测位置1/n的质量；有放回抽n次才模拟同样样本量下的重新采样。', '自助法是在经验分布里排练重复实验，排练次数不是新增证据。', {level:'入门'}),
    L('bootstrap-interval', '标准误、偏差与百分位区间：三个问题三种读法', ['标准误','偏差','百分位区间'], '知道自助统计量的散布与中心分别估计什么，并正确解释区间的近似性质。', 'bootstrap替身世界、方差、分位数、置信区间', [
      S('先把“会晃多大”和“偏向哪里”分开', '想象每一次重新采样都给出一个新估计。新估计围绕真实参数摇摆的典型幅度，是标准误；所有新估计的平均位置减去真实参数，是偏差。一个箭靶上，落点很集中但离靶心远，代表散布小而偏差大；两者不能互相替代。真实世界里我们看不见靶心和全部重新采样，bootstrap便把原估计θ̂暂作替身世界的参照，用θ̂*的散布估计标准误，用这些星号估计的均值减θ̂估计偏差。请始终记住这个“暂作”，它决定结果只是近似。'),
      S('把公式读成一串动作', '得到B个自助估计后，先算它们的平均值θ̄*。自助标准误是这些估计的样本标准差：各个θ̂*b减θ̄*，平方、求和、除以B−1、再开方。偏差估计则是θ̄*−θ̂，不是减去未知真参数。若B=4时四个估计为2、3、4、5，它们平均3.5，样本标准差为√(5/3)；如果原估计为3，偏差估计为0.5。这里只是演示计算，四次模拟远不足以稳定判断尾部分位数。标准误与原数据的样本标准差也不同：一个量的是估计量，一个量的是个体。'),
      S('百分位法为什么直观，又为什么不能迷信', '把θ̂*从小到大排序，取约2.5%与97.5%分位数，得到常见的95%百分位自助区间。直觉是让替身世界的大多数估计落在区间内，再借此近似真实参数的不确定范围。但这一步需要估计误差分布能被合理模仿；强偏差、边界、离散小样本、重尾、非光滑统计量等都可能使覆盖率很差。百分位法不是精确置信区间，更不是任何样本下都“95%保证”。不同软件的分位数插值约定还会使有限B的端点略有不同，所以答题要说明方法，不能只报两个数。'),
      S('报告结果应当留下哪些信息', '实际报告至少写原始样本量、重抽样方式、重复次数、目标统计量和区间方法，并检查异常值、依赖性与估计偏差。不要把“区间里有95%的自助估计”直接解释成“参数随机地以95%概率在这里”；在频率学派下参数固定，95%指重复整个采样并造区间的长期覆盖能力，且自助区间通常只是近似这一能力。增加B会让同一数据上的端点更稳定，却不能修复错误模型。若小样本均值有可信的正态模型，经典t区间也应成为比较对象，而不是被模拟自动取代。')
    ], '原估计为3，自助估计为2、3、4、5，求自助偏差估计和标准误估计。', ['自助均值为(2+3+4+5)/4=3.5。','偏差估计为3.5−3=0.5。','相对3.5的平方离差和为2.25+0.25+0.25+2.25=5。','除以B−1=3再开方，标准误估计为√(5/3)≈1.291。'], '偏差估计0.5；自助标准误约1.291；B=4仅供手算示范。', ['用自助估计的标准差代替原数据标准差，却仍声称它衡量单个个体的差异。','把百分位区间称为任何分布、任何样本量下都精确95%的区间。'], '原样本固定时，把重抽样次数从1000增加到100000，主要改善什么？', ['电脑模拟误差','原始样本的代表性','样本中缺失的尾部信息','真实总体的独立观测数量'], 0, '更多重抽样能更精确地描画同一个经验世界，不能保证这个经验世界更接近真实总体。', '先分清标准误、偏差、覆盖率，再给自助结果贴上“近似”的标签。'),
    L('bootstrap-parametric', '参数bootstrap：先拟合一个世界，再从里面采样', ['参数bootstrap','拟合分布','模型假设'], '比较从经验分布抽样和从拟合参数模型抽样的区别。', '参数估计、正态分布或指数分布、bootstrap', [
      S('两种替身总体，不是两种神奇电脑', '非参数自助法把看见的每个数据位置当作等权抽签纸；参数自助法则先选定一个分布家族，再用数据估计参数，最后从拟合出的完整分布抽签。若等待时间被建模为指数分布，我们不只会重抽已有的2、4、6，还能生成1.3或9.8这样的新数值。新数值来自模型假设，并非电脑获得了新的真实测量。两者的差别就在替身世界如何搭建：前者主要借经验分布，后者主动采用分布形状。形状若可信可能更有效率，形状若错也可能把错误稳定地重复一万次。'),
      S('四步算法里，重新估计这一步不能丢', '设真实分布属于Fθ，先从原样本估出θ̂；再独立生成一份样本量仍为n的星号样本，它们服从Fθ̂；随后对星号样本重新执行原先的估计或拟合过程，得到θ̂*以及需要的统计量；重复B次，观察散布、分位数或检验统计量。重新拟合很重要：要模拟的是“拿到一份新数据后统计流程输出什么”，不是把原来的参数数值原封不动抄B次。若流程里包含模型选择等操作，是否也要重做，应由你想估计的目标与方法理论决定，不能随意省略后再宣称估计了全部不确定性。'),
      S('用指数等待时间看清参数和单位', '指数分布的速率λ以每分钟次数为单位，均值是1/λ分钟。若独立样本2、4、6分钟的均值为4分钟，极大似然速率估计为1/4每分钟。参数bootstrap便从速率为0.25的指数分布生成三次等待，再算新均值或新速率。注意速率估计的平均不等于平均等待时间的倒数，因为取倒数是非线性变换。也不要因为原样本恰好没有小于2的值，就禁止参数自助样本出现更小值；拟合指数模型允许所有正值，这正体现了模型带来的外推。'),
      S('如何决定是否值得用它', '先问建模根据：等待是否近似无记忆、测量是否独立、是否有截尾或随时间变化的速率。再看拟合诊断及敏感性，不只看直方图像不像。参数自助区间仍可能受小样本偏差和边界影响，并不因为模型写成公式就自动精确。它尤其适合抽样分布难算、但能可信生成数据并重复拟合的场合。做题时可画箭头“原数据→估参数→拟合分布→新数据→重新估参数”，每个箭头写上依据。若题目要求零假设检验，生成分布还必须满足零假设，不能直接照搬无约束拟合。')
    ], '等待样本为2、4、6分钟，假定独立指数分布，参数自助法如何估计均值的波动？', ['原均值为4分钟，拟合速率λ̂=1/4每分钟。','每次从Exp(0.25)独立生成三次等待。','对每份星号样本重新算均值，保存为一个自助均值。','重复足够次数后用这些均值的样本标准差估计原均值的标准误。'], '从拟合指数分布生成新样本并重新取均值；不是只在2、4、6中重抽。', ['把指数分布的rate和mean混用；rate为0.25时均值是4。','只生成一次星号样本，便认为已经看到了统计量的抽样分布。'], '参数bootstrap最核心的额外假设是什么？', ['指定的参数分布家族能合理描述总体','电脑生成值越多就越接近任意真实总体','原样本必须没有重复值','真实参数必须事先已知'], 0, '参数自助法把拟合分布当作总体替身；分布家族是否合适会影响整个模拟的可信度。', '生成器多出来的形状来自假设；模型可信度决定参数自助法的地基。'),
    L('bootstrap-null', '自助检验：先让零假设在模拟世界里成立', ['bootstrap检验','零假设','p值'], '理解检验分布必须来自零假设，能给均值检验构造中心化样本。', '零假设、p值、样本均值、自助法', [
      S('检验问的是“假如”，不是“像不像原数据”', '检验H₀:μ=10时，问题是“假如总体均值真为10，像眼前这样极端的结果多常见”。因此生成参考分布的世界必须先满足μ=10。直接从均值为12的原样本重抽，星号均值会围着12晃，你实际模拟的是一个偏向原结果的世界，而不是零假设的世界。把这个分布拿来算p值，就像把被考察的结果提前放进标准答案。自助区间与自助检验相关，却不能不加条件地把同一个未经处理的重抽样流程到处复制。'),
      S('单样本均值的一种中心化构造', '在独立同分布、有限方差且通常需要足够样本等条件下，可先计算原均值x̄，把每个数据改为yᵢ=xᵢ−x̄+μ₀。这保留了样本残差的形状，同时把经验均值挪到零假设指定的μ₀。然后从y样本有放回抽n个，算星号均值。若选用未学生化统计量T=|x̄−μ₀|，每份星号样本也算T*=|ȳ*−μ₀|。比较同一种统计量、同一种双侧规则，数有多少T*至少与观测T一样大。更稳健的学生化方法还会除以各次重新估计的标准误，不能只对原统计量做这一操作。'),
      S('模拟p值怎样读，为什么不能写成零', '若B次模拟中有k次满足T*≥T，常见的带修正Monte Carlo报告为(k+1)/(B+1)，避免仅因模拟次数有限就报“概率为零”。这个修正不是使自助检验有限样本精确的魔法：参考分布本身仍是近似，检验成立还依赖条件和生成方式。p值也不是H₀为真的概率。它是在零假设与辅助假设都成立时，对至少如此极端结果的尾部度量。双侧检验应事先确定“极端”的含义；对称均值问题常用绝对偏差，偏斜或复合假设时要认真构造适当统计量。'),
      S('把适用范围写在答案里', '中心化重抽样适合这里的均值检验思路，不能机械推广成“把任何统计量减去观察值再加假设值”就得到有效检验。中位数、方差、边界参数或两组分布比较，各有自己的零假设约束与方法。若已知正态总体，可以在H₀约束下拟合方差并做参数模拟，也可直接用经典t检验；若数据来自同一个人的连续测量，独立重抽样更不能忽略相关。答题先写H₀，再写如何强制它成立，最后给统计量和尾部规则，这个顺序比背某个循环代码更可靠。')
    ], '原样本为10、12、14，检验H₀:μ=10。构造中心化经验样本；若B=999且有74次至少如此极端，报怎样的模拟p值？', ['原均值为12，观测绝对偏差T=|12−10|=2。','每个值减12加10，中心化样本为8、10、12，经验均值为10。','从8、10、12有放回抽三次，并用相同规则算T*。','按给定计数，带修正的模拟p值为(74+1)/(999+1)=0.075。'], '中心化样本(8,10,12)；给定计数对应p≈0.075，样本量极小，不能据此宣称方法精确有效。', ['从原样本直接重抽却称为零假设参考分布；它的均值仍在12附近。','把模拟p值解释成“零假设只有7.5%可能是真的”。'], '均值零假设检验中，中心化xᵢ−x̄+μ₀的主要作用是？', ['让模拟经验分布的均值满足零假设','增加原始样本量','保证所有统计量的检验都精确','把每个观测都变成μ₀'], 0, '中心化保留残差差异，却把经验均值移动到μ₀；这只是在合适条件下构造均值检验参考分布的一种办法。', '先造一个遵守零假设的世界，再看观察结果在那里有多罕见。'),
    L('bootstrap-limits', '为什么重抽一百万次，仍可能得出错得很稳的答案？', ['bootstrap边界','依赖数据','样本最大值'], '发现普通bootstrap的典型失效情形，并区分模拟精度与统计有效性。', 'bootstrap、独立同分布、统计量、置信区间', [
      S('电脑只会认真重复你交给它的世界', '你从一个班挑了五位熟人估计全校作息，无论怎样重抽这五位，都找不回没被覆盖的人群。自助法能够估计抽样波动，却不能自动修复选择偏差。另一个问题是依赖：连续五天的气温经常相似，随机打散后逐个重抽会把连续暖天、冷天的结构拆掉，得到的均值波动可能太小。时间序列常需要分块重抽等专门方法，分块长度与适用条件还要进一步讨论。不要把“非参数”误听成“无任何假设”：普通版本仍有抽样方式、独立性与正则性这些地基。'),
      S('用样本最大值看到最直白的边界', '假设真实总体在0到θ间均匀分布，θ未知。样本最大值Mₙ常被用来了解上界。普通非参数bootstrap只能从已有观测中抽，因此每份星号样本的最大值Mₙ*都不超过Mₙ。可是重新去真实总体采样，完全可能得到超过当前Mₙ的新值。自助世界在最需要探索的右端被硬生生截住了。更深的结果是，这类端点统计量的通常自助近似可能不一致。只看到星号最大值很稳定，并不能证明真实上界估计很精确；稳定可能只是替身总体的天花板压出来的。'),
      S('小样本、稀有事件与非光滑目标', '若十次观察都没发生事故，经验分布里的事故概率为零，普通重抽样也永远见不到事故；这不能推出真实风险为零。同样，少量数据里中位数可能只有几个取值，极端分位数和重尾均值可能非常不稳定。某些模型选择、阈值或边界问题还会让估计对数据的微小变化突然跳跃。是否可用bootstrap要针对统计量与模型判断，不是仅靠直方图光滑程度投票。合适的参数模型、精确方法、变换、学生化或专门重抽样有时能改善，但每一种改法都要说明新增条件，而非换个按钮就万事解决。'),
      S('一张检查单能比增加B更有价值', '先检查原样本是否代表目标总体，再检查采样单位是否独立，之后看统计量是否涉及端点、稀有尾部、边界或不连续选择。通过这些检查后，才讨论B是否够大、随机种子是否记录、端点是否随重复运行稳定。可以比较不同合理模型或不同方法对结论的影响，这叫敏感性分析。若结果差别巨大，应该诚实地说数据支持有限，而不是只保留最漂亮的一组数。统计推断的任务是把不确定性说清楚，不是把一个未经核查的近似算到很多小数位；精度与正确性是两条不同的轴。')
    ], '观测为1、3、4，非参数bootstrap样本最大值可能等于5吗？这说明真实总体不可能出现5吗？', ['经验分布的可抽取数值只有1、3、4。','任何有放回重抽样都只含这些数，因此星号最大值至多为4。','真实总体并未被证明只含这三个数，未来独立样本可能更大。','若目标是总体右端点，普通bootstrap的这个限制正提示需要专门理论或模型。'], '星号最大值不可能为5，但真实总体仍可能产生5。', ['认为B足够大就能观察到经验分布没有的稀有事件。','把自助分布的人工支持集当成真实总体的支持集。'], '下面哪一项最不能靠单纯增加重抽样次数解决？', ['原样本选择偏差','同一经验分布上分位数的Monte Carlo误差','同一经验分布上模拟标准误的小幅抖动','同一模拟流程中重复运行产生的随机差异'], 0, '更多电脑抽签不会让没有代表性的原数据变得有代表性。其余几项主要涉及可随B增加减小的模拟误差。', '先确认替身世界搭得合理，再把它模拟得精细。')
  ]));
  chapters.push(C('process', 12, '随机过程', [
    ['12.1','随机过程的概念',['process-slices']], ['12.2','随机过程的统计描述',['process-moments','process-joint']],
    ['12.3','泊松过程和维纳过程',['process-poisson','process-wiener']]
  ], [
    L('process-slices','随机过程：把一次随机结果，从一个数变成一整条轨迹',['随机过程','样本函数','时间切片'],'区分固定时刻、固定实验结果与完整随机过程。','随机变量、样本空间、函数',[
      S('一个数为什么不够用了', '掷一次骰子得到一个点数，用随机变量就能描述；记录每天的气温，或者从早到晚累计收到的消息数，结果是一串随时间变化的数。随机过程就是用时间等指标标记的一族随机变量{X(t):t∈T}。你可以把它想成尚未翻开的很多条未来轨迹，每次真实实验只揭开其中一条。随机不等于乱画：各时刻之间往往有关联，今天已经到来的消息仍包含在今晚的累计数里。研究过程，就是同时研究各时刻的分布与它们怎样共同变化，而不只画一条好看的曲线。'),
      S('沿两个方向切，就得到两个熟悉对象', '完整记号可写X(t,ω)。固定t=t₀而让实验结果ω变化，就像同时查看许多平行世界在中午的位置，得到随机变量X(t₀)。固定ω=ω₀而让时间t变化，就像追踪某一天从早到晚的记录，得到样本函数或一条轨道X(t,ω₀)。两个方向都固定时，只剩一个具体数。前面的随机变量理论并没有消失，而是被排成了一张“时间×实验”的大表。把这个表记在脑中，再看到均值函数、协方差函数就容易知道在对哪一方向做平均。'),
      S('时间连续不代表数值也连续', '按时间指标可分离散时间与连续时间，按状态取值又可分离散状态与连续状态，这是两条独立的分类轴。每天是否下雨是离散时间、离散状态；每天温度是离散时间、连续状态；任意时刻累计到店人数是连续时间、离散状态；理想布朗运动是连续时间、连续状态。不要把“连续时间”误读成路径必须连续，累计人数会在到达时跳跃。也不要把一条轨道的取值当成所有可能状态；今天只到过三位客人，不代表模型永远不能到四位。'),
      S('先确定指标与状态，才知道问题在问什么', '读题先问t代表秒、天还是实验轮数，X(t)代表当下状态、累计总数还是这段时间的增量。随后判断是在问固定时刻的概率，两个时刻的关联，还是整段路径事件。比如“十分钟内来三人”对应N(10)=3，而“第十到第十五分钟来三人”对应N(15)−N(10)=3，两者不能只把数字换个位置。真实观测只有一条轨道时，用时间平均估计总体平均还需要额外条件，不能因为点很多就自动视作很多独立实验；这也是后面各态历经性要解决的问题。')
    ],'N(t)表示开门后t分钟累计到店人数。N(5)、N(8)−N(5)、固定某一天的N(t)分别是什么？',['固定t=5，跨不同实验日变化的N(5)是随机变量。','N(8)−N(5)记录第五到第八分钟新增人数，是一个增量。','固定某天ω，t从0变化时画出的累计曲线是样本函数。','时间可连续取值而人数只能为整数，因此它是连续时间、离散状态过程。'],'分别是时间切片随机变量、三分钟增量、单条样本路径。',['把一条观测曲线当成整个随机过程；过程还包含其他可能轨道及其概率。','认为连续时间过程必有连续轨道，忽略计数过程的跳跃。'],'固定一次实验结果ω，令t变化，X(t,ω)是什么？',['一条样本路径','固定时刻的总体分布','一个常数，与t无关','整个样本空间'],0,'固定实验结果相当于选中一条未来轨迹；随时间读取它，就得到样本路径。','横着看一条轨迹，竖着看一个随机变量；过程把两者放在同一个模型里。',{level:'入门'}),
    L('process-moments','均值函数与协方差函数：一条平均轨迹，两点共同波动',['均值函数','自相关','协方差函数'],'将两时刻统计量拆成中心趋势和共同偏离，并区分相关函数的两种术语。','期望、方差、协方差',[
      S('均值是许多轨迹的纵向平均', '想象把同型号传感器重复启动很多次，每次都得到一条曲线。在同一时刻t把所有读数平均，得到m(t)=E[X(t)]。它不一定是任何一次真实实验的轨迹，也不等于沿某一条记录从头到尾平均。均值函数随t改变，说明总体中心位置在改变；即使它恒为零，波动强度和时刻之间的联系也可能改变。就像两群学生平均成绩相同，散布和配对关系仍能不同，所以只给一条平均轨迹远不足以描述随机过程。'),
      S('两个时刻相乘之前，要问有没有减均值', '本课明确使用R(s,t)=E[X(s)X(t)]表示未中心化的相关函数，使用C(s,t)=E[(X(s)−m(s))(X(t)−m(t))]表示协方差函数。它们满足C(s,t)=R(s,t)−m(s)m(t)。有些统计教材把“自相关函数”用于标准化协方差ρ，读不同资料时必须核对定义。C(t,t)就是方差，R(t,t)则是二阶矩，均值不为零时两者不同。先把单位也写出来：协方差的单位是读数单位的平方，而标准化相关系数没有单位。相同字母可能换义，定义比名称更可靠。'),
      S('用随机斜率让公式长出图像', '设X(t)=A+Bt，其中A、B独立，E[A]=1、E[B]=2，Var(A)=4、Var(B)=1。每次实验先抽出一个起点A和一条斜率B，之后整条轨迹都用这同一对数，所以不同时刻当然有关。平均轨迹为1+2t；减去均值后剩(A−1)+(B−2)t。展开两时刻乘积，交叉项因独立且中心化为零，得到C(s,t)=4+st。这里不能每到一个时刻就重新抽A、B，那会变成另一个过程，协方差结构也随之改变。记住随机系数在一次轨道内共享，是做题关键。'),
      S('协方差不仅是算出来的表，还要彼此兼容', '任取若干时刻及实系数，线性组合的方差都不能为负，这要求协方差矩阵半正定。因此并非随手画一条“看着像相关”的函数就能对应真实过程；还须满足对称性、非负对角线和更强的整体约束。遇到计算题，先求均值，再减均值展开，最后检查C(s,t)=C(t,s)以及C(t,t)≥0。一般过程的协方差为零只表示不相关，不推出独立；只有联合正态等额外条件下，零协方差才有更强意义。让每个公式都通过这些简单边界检查，能抓住很多漏项和误读。')
    ],'对上述随机直线，求m(2)、C(1,2)与R(1,2)。',['m(t)=1+2t，因此m(2)=5，m(1)=3。','独立中心化项交叉期望为零，C(s,t)=4+st。','代s=1,t=2得C(1,2)=6。','R(1,2)=C(1,2)+m(1)m(2)=6+15=21。'],'m(2)=5，协方差6，未中心化相关21。',['均值非零时把E[X(s)X(t)]直接当协方差。','在同一轨道不同时间重新抽取共享随机系数，悄悄换了模型。'],'对非零均值过程，C(s,t)等于哪一式？',['E[X(s)X(t)]−m(s)m(t)','E[X(s)X(t)]本身','m(s)m(t)','Var(X(s))+Var(X(t))'],0,'协方差先减去两个时刻各自的均值，展开后就是二阶乘积矩减均值乘积。','先减平均轨迹，再研究两个时刻怎样一起偏离。'),
    L('process-joint','单个时刻的分布，还没有告诉你轨迹怎样连起来',['有限维分布','高斯过程','独立性'],'理解过程需要联合分布，并辨别正态边缘与联合正态。','联合分布、边缘分布、独立、正态分布',[
      S('相同照片，可以剪成不同电影', '设每天温度的边缘分布都一样，你仍无法知道今天热是否意味着明天也热。一个模型每天独立抽签，另一个模型第一天抽一次后每天照抄；每一天单独看都能有同样分布，但连续轨迹完全不同。随机过程的有限维分布指任取有限个时刻，描述(X(t₁),…,X(tₖ))共同落在各个范围内的概率。它把“照片”之间的联系补进来。学习过程时不能只把单随机变量公式加上t就结束，因为最有意思的结构往往藏在不同时间的连接方式里。'),
      S('为什么均值和协方差通常仍不够', '均值记录一阶中心，协方差记录线性共同波动，它们并未穷尽所有联合关系。两变量可以协方差为零却共享很强的非线性联系，例如对称随机变量Z与Z²。更一般地，不同过程可能有相同均值与协方差，却有不同高阶关系和尾部行为。因此用二阶量概括过程需要承认视野范围：它非常有用，但不是任意分布的身份证。若题目仅给m和C，不能擅自断言所有概率事件都已确定；只有在某些指定分布家族中才够用。'),
      S('高斯过程的条件是“任意有限组联合正态”', '高斯过程要求对任意有限时刻，得到的向量都是多元正态，允许退化情形。它不是仅要求每个X(t)单独服从正态。联合高斯时，均值向量与协方差矩阵确定有限维分布，零协方差还可推出相应分量独立，这才让许多计算大幅简化。一个反例是Z为标准正态，S独立取±1且各半，令X=Z、Y=SZ；X和Y各自都标准正态，Cov(X,Y)=0，但|X|=|Y|始终成立，显然不独立，也不是联合二元正态。边缘正态不能替代联合条件。'),
      S('面对“独立”先检查它指哪一层', '一个过程可能有独立增量，却没有独立的各时刻取值；也可能两两不相关，却不满足任意有限组独立。做题时把待比较对象写全：是X(s)与X(t)，还是X(t)−X(s)与X(v)−X(u)，时间区间是否重叠？随后使用题给的联合分布、独立增量或高斯条件，而不是只凭协方差为零跳步。对于路径连续性等更精细的问题，有限维概率描述还要结合适当版本与路径条件；本课先把有限组随机变量的关系掌握好，不把二阶表格夸大成全部路径理论。')
    ],'Z~N(0,1)，S独立取±1且各半，令X=Z、Y=SZ。它们是否独立？',['S只改变正态变量的符号，故X、Y的边缘都为标准正态。','E[XY]=E[SZ²]=E[S]E[Z²]=0，所以协方差为零。','但是Y²=X²恒成立，知道X的绝对值就知道Y的绝对值。','因此不独立；它们不能是零协方差的联合二元正态向量。'],'边缘正态且不相关，但不独立，也不联合正态。',['只检查每个时刻都是正态，就宣布过程是高斯过程。','一般情况下看到零协方差就宣布独立。'],'高斯过程的正确定义要求什么？',['任意有限组时刻的向量都联合正态','只有每个时刻单独正态','所有轨迹都必须是直线','所有时刻值必然独立'],0,'联合正态包含时刻间的共同分布信息；单个边缘正态并不足够。','过程是整部电影的随机模型，不能只检查每一帧的直方图。'),
    L('process-poisson','泊松过程：数到目前为止来了几次',['泊松过程','独立增量','指数等待'],'在累计数、区间增量和等待时间之间正确切换。','泊松分布、指数分布、独立、随机过程',[
      S('泊松分布是一张照片，泊松过程是一段计数电影', '每小时平均来两次请求，只说明一个平均强度，还不足以认定是泊松过程；请求可能扎堆或有高峰。齐次泊松过程N(t)从N(0)=0起步，具有独立增量与平稳增量，长度h区间的新增次数服从均值λh的泊松分布。路径通常是逐次跳一的阶梯。λ是单位时间平均到达率，λh才是相应区间的平均次数。若时间单位改为分钟，速率也必须换单位。一个时刻的N(t)服从泊松分布，不等于已证明各区间的联合行为符合这个过程模型。'),
      S('独立的是不相交区间的新增量', 'N(2)包含前两分钟所有到达，N(5)又包含这部分，因此两者不独立。把后者拆成N(2)+[N(5)−N(2)]，不相交区间的两个增量独立，才能正确计算联合概率和协方差。由这个分解可知Cov(N(s),N(t))=λmin(s,t)，因为共享的历史贡献方差，后续独立新增不贡献协方差。均值与方差都是λt，随时间变大，所以N(t)本身不是平稳过程；平稳的是增量分布。此处两个“平稳”修饰的对象不同，不能省略宾语后混为一谈。'),
      S('第一次到达为什么等得像指数分布', '若T₁是首次到达时间，T₁>t当且仅当t之前一次都没来，即N(t)=0。因此P(T₁>t)=e^(−λt)，这就是速率λ的指数等待时间。相邻到达间隔在齐次泊松模型下独立且同为指数分布，均值1/λ。注意“平均每小时两次”不意味着每隔半小时准时来一次；平均间隔半小时仍容许很短与很长的等待。指数的无记忆性质也不是顾客真的会遗忘，而是这个模型给未来剩余等待的条件分布不依赖已等时长。'),
      S('做题先切区间，再写概率', '如果题目同时给出N(2)和N(5)的条件，把时间轴在2与5处切开，改用互不重叠的增量。若已知总区间到达数，子区间到达数可在齐次条件下用按长度比例的二项分布处理；这是条件问题，和无条件独立增量的表达不同。真实数据若有时变速率、同一事件引发后续连锁、批量到达或限制容量，要重新审查模型。概率计算的正确不仅依靠阶乘和指数，还靠把“累计”与“新增”翻译准确；画一条带分段的时间轴通常比立刻代公式更省力。')
    ],'齐次泊松过程速率λ=2/小时，求N(1)=1且N(2)=3的概率。',['把事件改写为第一小时1次、第二小时2次。','两段不相交，因此N(1)与N(2)−N(1)独立。','第一段概率为e^(−2)·2；第二段为e^(−2)·2²/2。','相乘得4e^(−4)≈0.07326。'],'4e^(−4)≈0.07326。',['把N(1)与N(2)当作独立；两者共享第一小时。','因增量平稳就说累计计数N(t)平稳；其均值与方差都在增长。'],'齐次泊松过程中，哪两个量可由独立增量直接判为独立？',['N(1)和N(3)−N(1)','N(1)和N(3)','N(2)和N(3)','N(3)和它自己'],0,'第一个对应(0,1]与(1,3]两个不相交区间的到达数；其他选项有共享历史。','先把累计计数拆成互不重叠的新增量，独立性才真正派上用场。'),
    L('process-wiener','维纳过程：累积微小扰动，却不是每刻独立换位置',['维纳过程','布朗运动','协方差'],'掌握标准布朗运动的定义、增量尺度和共同历史协方差。','正态分布、独立增量、协方差',[
      S('随机游走越走越细，会出现怎样的理想模型', '想象每一小步都有独立的正负扰动，把时间步长缩小，同时让一步扰动的典型大小按时间步长的平方根缩小，就会引出布朗运动的直觉。标准维纳过程W(t)满足W(0)=0，具有独立且平稳的增量，W(t)−W(s)服从均值0、方差t−s的正态分布，并且样本路径几乎处处连续。这里正态分布第二个参数是方差，不是标准差；经过四倍时间，方差变四倍，典型幅度只变两倍。理解这个平方根尺度，比把它误画成光滑正弦曲线更重要。'),
      S('位置共享历史，增量才可能独立', '对于s≤t，W(t)=W(s)+[W(t)−W(s)]，后面的新扰动与过去独立。因此Cov(W(s),W(t))=Var(W(s))=s，合写为min(s,t)。各时刻位置不独立，是因为晚时刻继承了早时刻已经累积的全部扰动。均值虽然恒为零，方差却为t，不满足二阶平稳。它拥有平稳增量，不等于自身平稳。若遇到W(3)−W(1)和W(4)−W(2)，两个增量共享(2,3]，协方差等于重叠长度1，不能因都叫“增量”就一律判成独立。'),
      S('连续不代表光滑，模型也不是现实粒子的显微照片', '理想布朗路径连续，却几乎处处不可微，不能像普通光滑函数那样给每个时刻写通常意义的速度。许多直觉错误来自把连续理解为“细看是一段直线”。数学模型用无数尺度上的扰动表达不规则性，现实测量总有时间分辨率，模型只是针对目标尺度的近似。带漂移和扩散的过程X(t)=μt+σW(t)有均值μt、方差σ²t；μ描述平均趋势，σ描述随机波动强度，σ不是方差。题目若写方差系数或扩散参数，需要先核对它究竟对应σ还是σ²。'),
      S('线性组合问题先写协方差，再算方差', '求aW(s)+bW(t)的方差时，不能只加两项方差，还要加2abCov(W(s),W(t))。布朗运动是高斯过程，所以有限个时刻的线性组合仍为正态；确定均值与方差后便能求概率。若组合可以改写成不相交增量，计算通常更直观。先画时间轴，拆出共同历史，再看是否重叠，往往一步就避免漏掉协方差。这里的模型结论基于完整布朗定义，不能仅凭每个W(t)边缘正态就推导同样结论；联合结构依然是电影的连接规则。')
    ],'标准维纳过程下，求W(3)−2W(1)的分布。',['布朗运动有限维向量联合正态，因此此线性组合正态。','均值0−2×0=0。','Var=Var(W(3))+4Var(W(1))−4Cov(W(3),W(1))。','代入3、1、min(3,1)=1，方差为3+4−4=3。'],'W(3)−2W(1)~N(0,3)，第二参数为方差。',['把W(1)与W(3)当成独立位置，从而漏掉协方差。','认为连续路径一定可微，或者把增量标准差写成t−s。'],'标准布朗运动W(5)−W(1)的标准差是多少？',['2','4','5','√5'],0,'增量方差是5−1=4，所以标准差为2。','晚时刻的位置继承过去；新增加的扰动才是新的独立部分。')
  ]));
  chapters.push(C('markov', 13, '马尔可夫链', [
    ['13.1','定义与例子',['markov-state']], ['13.2','多步转移概率的确定',['markov-power']],
    ['13.3','遍历性',['markov-balance','markov-classes','markov-limits']]
  ], [
    L('markov-state','马尔可夫性：“现在”必须装下预测所需的过去',['马尔可夫链','状态','转移矩阵'],'理解条件独立的含义，按行构造齐次链的转移矩阵。','条件概率、离散状态随机过程、矩阵',[
      S('不是世界没有记忆，而是状态足够说明问题', '预测明天设备是否故障，可能只需知道今天是正常还是故障，也可能还要知道已经用了几年。马尔可夫性说：在给定当前完整状态后，进一步知道更早历史，不再改变下一步的条件分布。它不是说过去与未来完全独立，而是说当前状态已经承接了模型需要的历史信息。若你把状态定义得太粗，例如只记录“机器在转”，却忽略温度和寿命，马尔可夫假设就可能不合理。状态设计是建模步骤，不是拿到数据就自动满足的事实。'),
      S('每一行是一张“从这里出发”的抽签表', '本课采用行向量约定：Pᵢⱼ=P(Xₙ₊₁=j|Xₙ=i)，行号是现在，列号是下一步。齐次指这个概率不随n改变。矩阵每个元素非负，每行之和为1，因为从某个状态出发下一步总要去某个状态。若当前分布为行向量pₙ，则pₙ₊₁=pₙP；不要与使用列向量的资料混乘。两状态例子P=((0.8,0.2),(0.3,0.7))表示从A出发有0.8留A、0.2到B，从B出发有0.3到A、0.7留B。它不要求每列也加到1。'),
      S('一条轨迹的概率按条件逐段相乘', '若已知X₀=A，路径A→B→A的概率是P_AB·P_BA=0.2×0.3，不需要再乘某个未知的初始概率。如果初始状态也随机，就先乘其初始分布中的相应概率。这里依靠的是条件概率乘法与马尔可夫性质，并非声称X₀、X₁、X₂独立。看到“只与当前有关”就把各时刻的边缘概率相乘，会丢掉转移机制。齐次也不表示每一步状态不变，只表示同样起点在不同日期采用相同的下一步抽签规则。'),
      S('如果需要前两天，试着把它们一起装进状态', '一个二阶天气模型可能依赖昨天和今天。单独把今天当状态时通常不是一阶马尔可夫，但可以把“昨天、今天”这个有序对作为新状态，下一步变为“今天、明天”。这叫扩展状态，不是消除了现实记忆，而是把记忆搬进当前描述。并非任何问题都该无限扩展：状态太大时估计转移概率会缺数据，仍需根据目标选择简化。做题先列状态空间和一步规则，再检查是否齐次及矩阵行和；比一开始就盲目做矩阵幂更能避免方向错误。')
    ],'P=((0.8,0.2),(0.3,0.7))，已知从A出发，路径A→B→A概率是多少？',['确认第一行表示从A出发。','A到B的概率是0.2。','在B时下一步到A的条件概率为0.3。','按条件链式法则相乘，得到0.06。'],'路径概率0.06；这是指定中间状态的路径，不是所有两步到A的总概率。',['把马尔可夫性误读成各时刻相互独立。','混用行向量和列向量约定，导致转移方向反了。'],'在行随机矩阵约定下，Pᵢⱼ表示什么？',['从当前i一步转到j的条件概率','从当前j一步转到i的条件概率','同时处于i和j的联合概率','状态i的长期频率必然为Pᵢⱼ'],0,'行是出发状态，列是到达状态；每行列出给定出发状态后下一步的完整概率分配。','当前状态不是一个标签而已，它应装下模型预测下一步所需的信息。',{level:'入门'}),
    L('markov-power','矩阵幂为什么能数出所有多步路径',['多步转移','矩阵乘法','Chapman–Kolmogorov'],'把矩阵乘法解释为对中间状态分路相乘再相加。','马尔可夫链一步转移、全概率公式',[
      S('两步到达，可以走不止一条路', '从A两步到A，可以先A再A，也可以先B再A。每一条指定路径的概率沿边相乘，不同中间状态对应互斥事件，最后把它们相加。对例子P=((0.8,0.2),(0.3,0.7))，两步A到A概率是0.8×0.8+0.2×0.3=0.70，而不只是对角线0.8的平方。矩阵乘法的“行乘列”就在帮你枚举中间状态。理解这点后，P²不再是一条神秘规则，而是全概率公式按表格一次计算所有起点和终点。'),
      S('把任意多步拆成前后两段', '令pᵢⱼ⁽ⁿ⁾表示从i经n步到j的条件概率。把m+n步拆成前m步到某个k，再用n步从k到j，就有pᵢⱼ⁽ᵐ⁺ⁿ⁾=Σₖpᵢₖ⁽ᵐ⁾pₖⱼ⁽ⁿ⁾。这就是Chapman–Kolmogorov关系。齐次链中一步矩阵始终相同，因此n步矩阵是Pⁿ，零步矩阵是单位阵I。若每一天有不同转移矩阵，应该按时间顺序相乘，不能一律写某个固定P的幂。每次做完乘法都检查非负与行和为1，能立刻发现许多漏项。'),
      S('当前状态不确定，也能用一行概率更新', '若今天在A、B的概率为p₀=(0.4,0.6)，明天在A的概率是0.4×0.8+0.6×0.3=0.5，明天在B为0.5。n步后pₙ=p₀Pⁿ。注意分布更新不是模拟一条实际轨迹，它描述许多同条件世界在该时刻的概率组成。一次观测只能看到A或B，不会看到“半个A半个B”，但概率向量能帮助你理解总体如何演化。初始分布不同会影响短期结果，在某些条件下长期影响才会逐渐消失。'),
      S('看到“恰好”“至少”要先翻译事件', 'Pⁿ中的元素表示“第n步位于j”，允许途中经过j、离开后再回来；它不是首次到达j的概率。若问n步内至少到过j，直接加各时刻P(Xₖ=j)会重复计算多次到达的轨道。可以改用首次到达分解、递推，或把目标状态改为吸收状态后计算尚未到达的概率，具体方法取决于问题。矩阵幂解决的是一个明确的终点事件，而不是替所有路径问题包办答案。读题时先把时间条件与是否允许重复经过写清，再选计算对象。')
    ],'对上述两状态链，求P²与p₀=(0.4,0.6)的一步分布。',['P²第一行第一列为0.8²+0.2×0.3=0.70。','第一行第二列为0.8×0.2+0.2×0.7=0.30。','第二行得到(0.45,0.55)，每行和为1。','p₀P=(0.4×0.8+0.6×0.3,0.4×0.2+0.6×0.7)=(0.5,0.5)。'],'P²=((0.70,0.30),(0.45,0.55))；一步分布(0.5,0.5)。',['把两步到A只算作两次留A，漏掉A→B→A。','把Pⁿ的终点概率误当第n步首次到达概率。'],'齐次马尔可夫链的(P²)ᵢⱼ等于什么？',['对所有中间k求和ΣₖPᵢₖPₖⱼ','Pᵢⱼ的平方','第i行所有元素平方后相加，与j无关','Pⱼᵢ'],0,'两步路径按中间状态分解；每条路径概率相乘，互斥路径再相加。','矩阵乘法是把全概率公式排成表，矩阵幂计算的是指定时刻的终点。'),
    L('markov-balance','平稳分布：整体流入与流出抵消，个体仍在移动',['平稳分布','平衡方程','长期占比'],'通过π=πP理解分布不变，并避免把它自动等同于任意初始分布的极限。','行概率向量、转移矩阵、线性方程',[
      S('浴缸水位不变，不等于每滴水没动', '一群用户每天在A、B两个应用之间切换，个人可能不停更换，但总体比例可能保持六成与四成。这就是平稳分布的直觉：用这个比例作为今天的分布，按转移规则推到明天，比例还是它。它说的是分布保持，不是轨道固定，更不是链停在某个状态。平稳分布π是非负且总和为1的行向量，满足π=πP。把方程右侧第j项展开，是所有来源i向j流入的概率质量之和；它恰好等于原本在j的质量。'),
      S('解方程时归一化条件不能省', '两状态链P=((0.8,0.2),(0.3,0.7))设π=(a,b)，方程a=0.8a+0.3b化为0.2a=0.3b，也就是从A流向B的质量与反向流量平衡，再加a+b=1便得a=0.6、b=0.4。一般链只需满足总流入平衡，不要求每一对状态的双向流量都相等；后者叫细致平衡，是更强的条件。在两状态例子里二者重合，不能因此误以为所有平稳链都可逐边配平。齐次有限状态链至少有平稳分布，但可能不唯一。'),
      S('平稳启动能保证哪些事', '若X₀按π分布，齐次链每个时刻的边缘分布都为π；进一步它的有限维联合分布对整体平移也保持不变，所以得到了平稳过程。若X₀确定为A，最初分布是(1,0)，当然还不是π。是否随着时间趋向π，要看沟通结构与周期性等条件，不能只因为方程有解就宣布。平稳分布属于转移机制，当前分布还取决于如何启动。计算时先解出候选向量，检查非负、归一化与代回，再单独讨论是否有长期收敛。'),
      S('长期比例与某一步概率也需分开', '在有限不可约链中，单条轨道对各状态的长期访问比例会趋向唯一π，即使链有周期；而从固定状态出发的第n步分布可能因周期振荡而不收敛。这说明“长期占多少时间”与“很晚某个固定时刻在哪里”不是同一问法。不可约有限链中从状态j出发的平均首次返回步数为1/πⱼ，这是平稳占比的另一种解释，但不能不检查条件就用于任意可约链。理解这些区别，能让平衡方程从一道纯代数题变成关于动态系统的精确描述。')
    ],'求P=((0.8,0.2),(0.3,0.7))的平稳分布，并说明它不表示什么。',['设π=(a,b)，写π=πP。','第一式化成0.2a=0.3b，即a:b=3:2。','加归一化a+b=1，得到a=0.6,b=0.4。','代回得到(0.6,0.4)，说明比例不变，但个体仍按P切换。'],'π=(0.6,0.4)；不是每条轨道都固定不动，也不是无需条件便有任意起点收敛。',['忘记π各项和为1，得到整条数乘解却当作概率分布。','以为所有平稳分布都满足每条边的双向流量相等。'],'π=πP的直接含义是什么？',['以π启动后一步分布仍为π','所有转移都停止','从任意初始状态必然一步达到π','每一列P都必须和为1'],0,'这是分布不变的定义；收敛速度与任意起点的长期行为是另外的问题。','平稳描述总体比例的守恒，不能直接替代收敛结论。'),
    L('markov-classes','不可约、周期、吸收：先看路网再谈长期',['不可约','周期性','吸收状态'],'用转移图理解有限链的结构条件与不同长期结局。','马尔可夫链、可达、多步转移',[
      S('把正概率转移画成有向路网', '若从i出发经若干步有正概率到j，就称j从i可达；若双方可达，称它们互通。不可约意味着所有状态都在一个互通类中，像一座道路连通的城市，任何地方都有可能最终到任何地方。一步概率为零不等于永远不可达，中间绕行也算路。闭类指进入后不能以正概率走到类外；单个只会留在自己的状态就是吸收状态，Pᵢᵢ=1。看清这些结构，才能知道质量会不会被困在不同区域，以及平稳分布为何可能不唯一。'),
      S('周期是返回时间的共同节拍', '对状态i，收集所有可能返回i的正整数步数，取它们的最大公约数作为周期。A、B每步必互换的链只能偶数步回到原点，周期为2。若某状态有正概率自环，便可以一步返回，它的周期为1；在不可约链中所有状态周期相同，所以一个自环就足以让整条不可约链非周期。自环是充分线索，不是非周期的必要条件；即使没有自环，若能在2步和3步返回，最大公约数仍为1。周期说的是可能步数的结构，不是平均多久返回。'),
      S('吸收链展示初始状态的影响', '考虑A、B都是吸收状态，C下一步以1/4进A、3/4进B。所有质量最终被困在A或B，且最终比例取决于起点。δ_A、δ_B及它们的混合都是平稳分布，因此不能像不可约情形那样期待唯一长期比例。这里从C出发一步就吸收，真实题目也可能需要多步递推才能算吸收概率。平稳分布依然存在，却无法单凭“存在”回答从C最后进A的概率；应把起点和吸收事件放进计算。可约不是方法失效，而是系统确实有多个长期区域。'),
      S('有限与无限不要混套结论', '有限不可约链自动具有正常返性，因而存在唯一平稳分布；对可数无限状态链，不可约本身不保证能归一化出平稳分布，还需正常返等条件。遍历性一词在不同教材中可能涵盖不可约、非周期及返性等不同组合，做题应回到书中的具体定义。本课的收敛结论明确限定有限、不可约、非周期。看到一个矩阵，先查有向可达性、闭类、返回步数，再写结论，比背“任何转移矩阵都有唯一稳定解”可靠得多。')
    ],'A与B必互换的链周期是多少？若在A增加正概率自环且仍可到B，结构会怎样？',['原链A回A只能经过2、4、6…步。','这些返回步数的最大公约数为2，链周期为2。','加入A自环后，A可一步返回，周期变1。','若A、B仍互相可达，链不可约，两状态共同非周期。'],'原链周期2；保持不可约并加入A自环后成为非周期链。',['把一步不能到达等同于不可达，忘记多步路径。','以为没有自环就一定有周期；长度互素的返回路径也能形成非周期。'],'有限不可约链再加哪项条件，可保证从任意初始分布的时刻分布趋向唯一平稳分布？',['非周期','每个元素都必须等于1/状态数','必须有吸收状态','必须从平稳分布启动'],0,'有限不可约保证唯一平稳分布，非周期消除固定时刻分布的周期振荡。','先看道路能通到哪，再看返回有没有固定节拍。'),
    L('markov-limits','平稳分布存在，为什么分布仍可能来回振荡？',['遍历性','极限分布','时间平均'],'用周期反例与两状态递推区分存在、唯一和收敛。','平稳分布、不可约、周期、概率分布更新',[
      S('一个最小反例就能拆开三个词', 'A、B每步必互换，矩阵P=((0,1),(1,0))。它是有限不可约链，平稳分布唯一为(1/2,1/2)。然而从A出发，第偶数步一定在A，第奇数步一定在B，时刻分布永远在(1,0)与(0,1)之间摇摆，不存在通常意义的极限。与此同时，沿一条长轨道数访问次数，A与B各占约一半。于是平稳分布的“存在”、平稳分布的“唯一”、任意起点时刻分布的“收敛”，以及时间占比的“趋近”，四件事被清楚分开了。'),
      S('标准有限链收敛结论的条件', '对于有限状态、齐次、不可约且非周期的链，唯一平稳分布π存在，而且任意初始分布p₀都有p₀Pⁿ→π。这里有限避免了无限链的返性问题，不可约避免了长期区域分裂，非周期消除固定节拍的振荡。各条件不是为了显得严谨而堆的形容词，它们分别排除了具体失败方式。若一开始就按π启动，即使有周期，各时刻分布也始终π；这不等于说从任意其他起点会收敛。写证明或解题时，先说明是在何种起点下讨论何种极限。'),
      S('两状态递推能看见遗忘起点的速度', '对P=((0.8,0.2),(0.3,0.7))，设aₙ=P(Xₙ=A)，则aₙ₊₁=0.8aₙ+0.3(1−aₙ)=0.3+0.5aₙ。平衡点为0.6，相减得aₙ₊₁−0.6=0.5(aₙ−0.6)，故aₙ=0.6+0.5ⁿ(a₀−0.6)。若从A出发，a₀=1，第四步为0.6+0.4/16=0.625。这个公式不仅算出极限，还表明起点的影响按每步一半衰减。不同链衰减可慢得多，不能把“最终收敛”理解成“几步之后已足够接近”。'),
      S('长期规律不是对每次轨道的承诺', 'π_A=0.6不代表任何连续十步都恰好六次A，也不表示第十步一定在A。它给的是分布或长时间频率的极限描述，有限样本仍有波动。实际估计转移机制还会有参数误差，模型齐次性也可能随环境改变。做题时可把答案分四栏：结构条件、平稳向量、是否时刻收敛、若需要则给收敛速度；反例检查用必互换链和两个吸收态链就能覆盖很多错误。理解“哪种平均”“哪种极限”，比单独背住遍历两个字更能带你进入后面的平稳过程与时间序列。')
    ],'P=((0.8,0.2),(0.3,0.7))，从A出发第四步在A的概率和极限分别是多少？',['写aₙ₊₁=0.3+0.5aₙ，初值a₀=1。','平衡点解a=0.3+0.5a，得到0.6。','递推差值aₙ−0.6=0.5ⁿ×0.4。','n=4得到0.625；n趋无穷时0.5ⁿ趋零，极限为0.6。'],'第四步0.625，极限0.6；并非第四步就已经精确等于平稳概率。',['有唯一平稳分布就认定时刻分布必收敛，漏看周期。','将长期占比0.6解释为每十步都恰好六次。'],'对必互换的两状态链，从A启动时正确说法是哪项？',['平稳分布唯一，但时刻分布不收敛','没有平稳分布','从第二步起分布恒为各半','长期时间占比不可能各半'],0,'唯一平稳分布为各半，但固定起点产生奇偶交替；时间访问比例仍趋各半。','存在的平衡、走向平衡和沿路平均，是三个需要分别回答的问题。')
  ]));
  chapters.push(C('stationary', 14, '平稳随机过程', [
    ['14.1','平稳随机过程的概念',['stationary-types','stationary-phase']],
    ['14.2','各态历经性',['stationary-ergodic']], ['14.3','相关函数的性质',['stationary-covariance']],
    ['14.4','平稳随机过程的功率谱密度',['stationary-spectrum','stationary-discrete-spectrum']]
  ], [
    L('stationary-types','平稳不是“一条线不动”，而是换起点后统计规则不变',['严格平稳','宽平稳','时间平移'],'区别严格平稳、二阶平稳与平稳增量，掌握它们的条件关系。','随机过程、联合分布、均值与协方差',[
      S('先把“平稳”的主语换成统计规则', '你观察一段噪声，曲线一直上下跳，仍可能平稳；你看到一条平滑上升的直线，反而往往不平稳。平稳关心的是把整段观察窗口往后挪后，概率规则有没有变，而不是眼前轨迹是否水平。严格平稳要求任取有限个时刻，把它们一起平移h，得到的联合分布不变。强调一起平移，是保留时刻间距离；强调联合，是不仅看每一刻的直方图，还看两刻、多刻的关联。只说每一刻分布相同，尚未覆盖所有联合结构。'),
      S('宽平稳把要求缩到二阶统计量', '二阶或宽平稳通常要求二阶矩有限、均值m(t)=μ为常数，协方差C(s,t)只依赖时间差τ=t−s。方差因而固定为C(0)。对均值恒定的过程，未中心化相关R(τ)=C(τ)+μ²也只依赖时间差。它不要求所有高阶联合分布不变，所以比严格平稳在二阶存在时更弱。严格平稳若二阶矩不存在，就不能直接套宽平稳定义；严格平稳且二阶矩有限才推出宽平稳。学习时把“矩存在”也列成条件，不要把它从定理中悄悄删掉。'),
      S('弱一点的条件为什么仍很有用', '许多预测与信号分析主要利用线性关系，均值、方差与协方差已经足以支撑大量计算。若过程是联合高斯，有限维分布由均值和协方差决定，因此宽平稳还能推出严格平稳；这里必须是高斯过程，不能只检查各时刻边缘正态。一般反例可取独立序列，偶数时刻标准正态、奇数时刻对称取±1：均值都0，方差都1，非零时差协方差都0，所以宽平稳，但单时刻分布随奇偶改变，并非严格平稳。二阶描述确实有意忽略了一部分信息。'),
      S('用三步检查，避开名字相近的陷阱', '检验宽平稳时先求均值是否常数，再求方差是否有限，最后把协方差写成s、t的函数，看能否化为仅依赖t−s。标准布朗运动虽然均值为零，方差为t，已经不平稳；齐次泊松计数均值λt也不平稳。它们都拥有平稳增量，即等长区间新增量的分布相同，但累计过程仍会扩散或增长。做题不要因为看到stationary这个词就直接下结论，要读清它修饰的是过程、增量，还是一个马尔可夫链的分布。时间窗口能否平移，是最核心的检查方向。')
    ],'独立序列中，偶数时刻标准正态，奇数时刻取±1各半。它宽平稳吗，严格平稳吗？',['各时刻均值都是0，二阶矩有限且方差为1。','不同时刻独立，协方差为0；同一时刻为1，只依赖时差是否为0。','因此它是宽平稳序列。','但偶数与奇数时刻的单变量分布不同，平移一步已改变分布，所以不严格平稳。'],'宽平稳，但不严格平稳。',['认为平稳路径必须水平或几乎不波动。','无条件写“严格平稳推出宽平稳”，漏掉有限二阶矩。'],'什么额外条件使宽平稳可以推出严格平稳？',['过程的任意有限组都联合高斯','只有每个时刻均值为零','只有方差有限','轨迹画起来很平滑'],0,'高斯有限维分布由均值和协方差确定，宽平稳使这些参数平移不变，从而使联合分布不变。','平稳是统计规则对时间起点不敏感，不是某次实现停止运动。'),
    L('stationary-phase','随机相位正弦：为什么每条轨迹在振荡，整体却平稳',['随机相位','相关函数','周期过程'],'借一个可算模型理解平稳性、时差与总体平均。','三角恒等式、均匀分布、均值与协方差',[
      S('把随机性放在起跑位置，而不是每个时刻', '设X(t)=Acos(ω₀t+Θ)，振幅A为固定常数，角频率ω₀非零，初相位Θ在0到2π上均匀。每次实验只抽一次Θ，之后按同一条正弦走。所有轨迹波形相同，起跑位置不同；在任一固定时刻查看大量实验，相位仍均匀分散，整体中心为零。若每到一个时刻重新独立抽相位，就变成另一种过程，不再是这些连续的正弦轨道。看似相似的表达，随机量在何时重抽，决定了完全不同的连接方式。'),
      S('整体平移相当于重新命名均匀相位', '把所有时刻共同平移h，ω₀(t+h)+Θ=ω₀t+(Θ+ω₀h)。相位按2π取模后，均匀分布仍是均匀分布，因此任意有限组时刻的联合分布不变，这给出了严格平稳的直接理由。不是因为单个时刻均值为零就够了，而是整个有限维向量都可用同一新相位描述。若相位固定为0，得到确定的cos(ω₀t)，均值函数就是这条非恒定曲线，通常不平稳。随机化相位在这里恰好抹去了绝对起点的特殊性。'),
      S('乘积公式让“只看时差”显形', '利用cos u cos v=[cos(u−v)+cos(u+v)]/2。取u=ω₀s+Θ、v=ω₀t+Θ，第一项不含Θ，第二项绕完整相位平均后为零。于是R(s,t)=A²cos[ω₀(t−s)]/2。因为均值为零，C=R，方差为A²/2，相关只看时间差。相隔一个周期的值完全一致，半个周期恰好反号，四分之一周期协方差为零；但零协方差不代表对应值独立，它们仍来自同一个相位，受到共同几何约束。这个例子能把“二阶相关”与“全部依赖”分清。'),
      S('这也为频谱与各态历经埋下线索', '它的能量集中在一个正弦频率上，所以频域应出现正负ω₀处的谱线，而不是随便一条光滑密度。谱线要用谱测度或广义函数理解，不能直接塞进要求协方差绝对可积的普通傅里叶积分。沿一条固定振幅轨道作足够长时间平均，正负部分抵消而趋于零；若振幅也随机，每条轨道的平方时间平均会固定为自身振幅平方的一半，未必等于跨轨道平均。这提醒我们，平稳性、时间平均能否代表总体、谱是否有普通密度，各自都有独立的问题要回答。')
    ],'A=2、ω₀=π，Θ均匀，求均值、方差与相隔1时的协方差。',['均匀相位使E[cos(πt+Θ)]=0，故均值0。','方差A²/2=2。','C(τ)=2cos(πτ)。','τ=1时cosπ=−1，故协方差−2，表示恰好反号。'],'均值0，方差2，C(1)=−2。',['把“固定相位的确定正弦”也当作同一个平稳模型。','认为相关为负不合法；协方差允许负，但整体必须半正定。'],'随机相位正弦整体平移h后仍同分布，最直接的原因是什么？',['均匀相位加常数再按2π取模仍均匀','每条轨迹都不变','不同时间都相互独立','正弦的所有值都等可能'],0,'整体时间平移只把初相位加一个常数，均匀相位的分布保持不变。','绝对起点被均匀相位冲淡后，振荡可以与平稳共存。'),
    L('stationary-ergodic','各态历经：一条足够长的记录，能代替许多次实验吗？',['各态历经','时间平均','总体平均'],'用随机常数反例区分平稳与各态历经，理解均值与相关的不同要求。','平稳过程、期望、协方差、积分或求和平均',[
      S('现实里我们经常只有一条很长的曲线', '理论均值E[X(t)]是同一时刻跨许多实验结果的平均，实际却可能只有一台传感器连续工作很久的数据。把同一条轨迹的时间平均拿来替代总体平均，需要额外保证，这正是各态历经思路。平稳性说统计规则不随起点变，各态历经性进一步问一条长轨道是否能充分探索总体中的随机变化。它不是把很多时刻机械算作很多独立样本；即使相邻值有依赖，只要长期能够适当“走遍”，时间平均仍可能有代表性。依赖强到永远困在某类轨道时就会失败。'),
      S('最短的反例：开机抽一次，以后永远不变', '设A以各半概率取±1，过程X(t)=A。跨实验看任何时刻，均值0、方差1，任意联合分布平移后都不变，所以严格平稳且宽平稳。但在一次实验中，轨道永远是+1或永远是−1。无论观察多久，时间平均都还是A，绝不靠近总体均值0。你收集了一百万个时刻，却只重复读取同一个随机选择。这说明“长时间”“平稳”“观测点很多”不能自动保证估计可靠，关键在新时间点带来多少真正不同的信息。'),
      S('协方差怎样帮助检查均值时间平均', '对于宽平稳过程，长度T的时间平均X̄_T=(1/T)∫₀ᵀX(t)dt，其方差等于(1/T²)∫₀ᵀ∫₀ᵀC(t−s)dtds；在实值情形可写成(2/T²)∫₀ᵀ(T−τ)C(τ)dτ。若它趋零，时间平均在均方意义下趋于总体均值。协方差绝对可积是常见的充分条件，会使这个方差压向零；这不是必要条件，更不是所有形式各态历经性的完整定义。随机常数C(τ)=1使方差始终为1，正好解释为何平均无法冲淡那一次共同随机选择。'),
      S('均值能代替，不代表所有统计量都能代替', '教材可能分别讨论均值各态历经、相关函数各态历经等二阶性质，而概率论中的完整遍历性要求更广。必须说清在讨论哪个统计量、哪种收敛。随机振幅正弦的长期均值可能都为零，但每条轨道的平均平方取决于固定振幅，未必等于总体二阶矩，所以均值表现良好也不代表相关估计可靠。做题先写总体目标，再写单轨道时间平均，最后检查它们差的方差或理论条件；实际数据只有有限长度，样本图像“看起来跑遍了”只能提供线索，不能替代模型依据。')
    ],'A=±1各半，X(t)=A。算总体均值与任意长度时间平均，判断均值各态历经。',['总体均值E[A]=0。','固定一条轨道后X(t)一直等于同一个A。','时间平均(1/T)∫₀ᵀA dt=A，对任意T都如此。','与0的均方误差E[A²]=1不趋零，因此不具均值的均方各态历经性。'],'过程平稳，但时间平均始终为±1，不能代替总体均值0。',['认为严格平稳必然各态历经。','证明均值时间平均收敛后，未经进一步条件便推广到所有统计量。'],'哪个现象最能说明平稳不等于均值各态历经？',['每条轨道恒为随机±1，总体均值0','独立同分布均值0的长样本平均趋零','一条曲线上下波动','样本均值偶尔为负'],0,'随机常数过程平移后分布不变，但每条轨道永远留在自身常数，长平均无法得到总体均值。','平稳保证规则不换，各态历经才讨论单条长轨道能否代表总体。'),
    L('stationary-covariance','相关函数不能随便画：对称、界限与半正定',['协方差合法性','半正定','相关系数'],'使用简单必要条件筛查候选协方差，并理解整体非负方差约束。','方差、协方差、不等式、平稳过程',[
      S('每个相关值都要属于同一个共同世界', '给定平稳实值过程的协方差C(τ)，它不只是每个时差各填一个数字；这些数字必须能同时来自一族真实随机变量。C(0)是方差，必须非负；交换两时刻不改变协方差，故C(−τ)=C(τ)；柯西不等式给|C(τ)|≤C(0)。这些条件容易检查，但还不够。像设计一张地图，任意两点的距离看起来合理，也可能无法同时放进同一空间；协方差也有整体兼容性。每个候选函数都要接受线性组合方差不能为负的检验。'),
      S('半正定就是“任何加权组合都不能有负方差”', '任取时刻t₁到tₙ与实系数a₁到aₙ，Var(ΣaᵢX(tᵢ))=ΣᵢΣⱼaᵢaⱼC(tᵢ−tⱼ)≥0。这称协方差函数的半正定性。名字听起来抽象，但本质只是方差非负。对零均值过程，C与未中心化相关R相同；均值μ不为零时R(τ)=C(τ)+μ²，不能把两者的零时差都叫“方差”。若标准化为ρ(τ)=C(τ)/C(0)，还需C(0)>0；零方差过程几乎处处恒于均值，不能照常除以零来定义相关系数。'),
      S('两两都没越界，整体仍可能不可能', '假设三个连续时刻的方差均为1，邻接协方差为1，而隔两步协方差为−1。单独看每一对都满足绝对值不超过1，但邻接协方差1意味着X₀−X₁方差为零、X₁−X₂方差也为零，中心化后它们应几乎处处相等，因而X₀与X₂不可能反号。更直接地，系数(1,−1,1)的组合方差会是−3，暴露出矛盾。所以偶函数、零点最大和幅度界限只是快速筛查，不能代替完整半正定性。'),
      S('做题时怎样选择检查的层次', '若候选函数在某个时差大于C(0)，立即判不合法；若基本条件通过，再尝试小阶协方差矩阵或给出构造证明。比如C(k)=σ²ρ^|k|且|ρ|<1可由平稳AR(1)模型构造；C(τ)=A²cos(ωτ)/2可由随机相位正弦构造。找到明确过程往往比硬验所有矩阵更直观。反过来，协方差在某些滞后为负不代表非法，反向波动完全可能。不要把“最大在零点”误听成“每处都非负”，更不要凭一张画得平滑的曲线就认定可用作模型。')
    ],'候选三个时刻协方差矩阵为[[1,1,−1],[1,1,1],[−1,1,1]]，用a=(1,−1,1)判断合法性。',['对角线贡献a₁²+a₂²+a₃²=3。','三对交叉项依次为2(1)(−1)(1)=−2、2(1)(1)(−1)=−2、2(−1)(1)(1)=−2。','总和3−2−2−2=−3。','方差不可能为负，所以这个矩阵不半正定，不能来自真实过程。'],'不合法；尽管每个非对角元素的绝对值都未超过1，整体仍矛盾。',['把C(τ)某处为负当作不合法的充分理由。','只检查|C(τ)|≤C(0)，以为这已经保证任何候选都有效。'],'协方差半正定性最朴素的含义是什么？',['任意有限线性组合的方差都非负','所有时差协方差都严格为正','每条轨迹都单调','各时刻都相互独立'],0,'半正定约束的是整体二次型，它来自任何随机变量方差不能为负这一基本事实。','相关函数是一张共同可实现的关系网，不能逐个数字各自随意指定。'),
    L('stationary-spectrum','功率谱：把“隔多久还相似”翻译成“哪些频率在贡献”',['功率谱密度','傅里叶变换','连续时间'],'理解时间相关与频率分布的互译，并固定角频率下的归一化约定。','宽平稳、协方差、积分、正弦频率',[
      S('同一份波动，可以按时间差也可以按频率看', '看海面起伏时，你既能问相隔几秒的高度是否相似，也能问波动主要是慢慢涌起还是快速颤动。协方差函数回答前者，功率谱描述后者，它们是对二阶结构的两种语言。这里的功率不是电路中才能出现的瓦数，而是按模型单位计的平均平方或方差。把谱画成频率上的“波动预算”，各频段面积反映该频段贡献多少二阶变化，比一开始死记复指数公式更容易建立直觉。但谱只描述二阶结构，不自动决定任意非高斯过程的全部分布。'),
      S('先固定单位和傅里叶约定，再谈面积', '本课连续时间采用角频率ω，单位为弧度/时间，并对中心化过程定义S_C(ω)=∫从负无穷到正无穷 C(τ)e^(−iωτ)dτ；逆变换C(τ)=(1/2π)∫S_C(ω)e^(iωτ)dω。在适当可积条件下，Var(X(t))=C(0)=(1/2π)∫S_C(ω)dω。若换用每单位时间多少周期的频率f，则ω=2πf，公式中的2π位置会随定义改变。看到不同资料差一个2π，先查单位与变换约定，不能立即判谁算错。'),
      S('均值、谱线和普通密度要分清', '若使用未中心化R(τ)=C(τ)+μ²构造总功率谱，非零均值产生零频处的谱线，贡献μ²；中心化协方差谱只记录随机波动的方差。随机相位正弦也会产生±ω₀处谱线，它的相关函数不绝对可积，不能直接当作普通连续密度来积分。更一般地，平稳过程有谱测度，但未必有处处普通函数意义的谱密度。本课先掌握可积协方差的普通变换，再认识谱线是需单独说明的边界，不用一个公式假装所有过程都只有光滑谱。'),
      S('用指数协方差观察慢与快', '若C(τ)=σ²e^(−a|τ|)，a>0，其角频率谱为S_C(ω)=2aσ²/(a²+ω²)。a越小，时间相关衰减越慢，谱越集中在零频附近；a越大，记忆短，频率分布更宽。对实值过程S非负且为偶函数，积分按上述约定回到σ²，提供重要自检。求题时先写C还是R、连续还是离散、ω还是f，再做变换和面积检查。频谱峰值高并不意味着总方差必大：同样面积可以集中成窄峰，也可以分散成较矮的宽谱。')
    ],'若C(τ)=4e^(−2|τ|)，用本课角频率约定求谱并核对方差。',['识别σ²=4，a=2。','代入S_C(ω)=2aσ²/(a²+ω²)，得16/(4+ω²)。','积分∫从负无穷到正无穷16/(4+ω²)dω=8π。','再乘1/(2π)，恢复C(0)=4。'],'S_C(ω)=16/(4+ω²)，总谱面积8π，在本约定下方差为4。',['混用Hz频率与角频率公式，漏掉2π。','把非零均值带来的零频谱线混进方差，却仍称为中心化协方差谱。'],'本课连续时间角频率约定下，中心化谱的积分怎样得到方差？',['Var=(1/2π)∫S_C(ω)dω','Var=∫S_C(ω)dω且永远无系数','Var=S_C(0)','Var必等于谱峰的高度'],0,'由逆傅里叶变换取τ=0，得到方差等于谱积分乘1/(2π)；换约定时系数会改变。','频谱和相关是在用不同坐标描述同一份二阶波动；先写约定再算。'),
    L('stationary-discrete-spectrum','离散时间谱：只看一个频率周期，白噪声为什么是平的',['离散功率谱','白噪声','混叠'],'把离散协方差序列与周期谱联系起来，区别连续时间积分约定。','平稳序列、协方差、求和、复指数',[
      S('按天记录后，频率也有重复的别名', '离散时间n只取整数，e^(i(ω+2π)n)=e^(iωn)，因此相差2π的角频率在采样点上完全相同。离散时间谱天然以2π为周期，通常只看[−π,π]这一段；它不同于连续时间谱在整个实数轴上积分。频率单位是弧度/采样间隔，若每天采一次，就要结合一天的间隔解释真实周期。不同连续振荡可能在稀疏采样点上留下同样数列，这称混叠。画谱前先知道采样间隔，否则再漂亮的峰也可能被解释成错误时间尺度。'),
      S('本课选一个含1/(2π)的密度定义', '对零均值或已中心化的平稳序列，设γ(k)=Cov(Xₙ,Xₙ₊ₖ)。若协方差绝对可求和，定义f(ω)=(1/2π)Σ从k=−∞到∞ γ(k)e^(−ikω)，ω∈[−π,π]；逆式γ(k)=∫从−π到π f(ω)e^(ikω)dω。因此方差γ(0)=∫f(ω)dω。这和前篇连续时间S_C的系数放置不同，是明确的定义选择，不是矛盾。也有资料把离散谱定义为不带1/(2π)的S，届时逆式需补系数。遇题先抄清本题约定，不要机械搬运。'),
      S('白噪声的平，不是每次观测值都相同', '二阶白噪声满足均值0、方差σ²恒定、非零滞后协方差为0。代入只剩k=0一项，f(ω)=σ²/(2π)，所有频率密度相同，所以借用了白光均匀混合频率的名字。它描述不相关，不保证各时刻独立，更不保证正态；独立同分布有限方差噪声是一个常见特例。相邻白噪声相加形成移动平均后，邻接观测共享同一扰动，谱便不再平坦。比如Xₙ=εₙ+θεₙ₋₁的谱为σ²(1+θ²+2θcosω)/(2π)，可从共享项或滤波两种角度理解。'),
      S('面积检查与峰值解释要一起用', '当σ²=1、θ=1/2时，移动平均方差1.25，邻接协方差0.5，谱为(1.25+cosω)/(2π)。零频处比π处高，表示慢变化成分更强；若θ为负，强弱会反过来。积分后cos项消失，留下方差1.25，这能检查漏系数或平方的错误。谱为非负函数对应协方差半正定；但有谱线时仍需谱测度，不应硬用普通密度解释。做题按连续/离散、频率单位、中心化与否、归一化系数四项先定位，再求和或变换，许多看似高等的错误其实来自这四项混用。')
    ],'εₙ为方差1的白噪声，Xₙ=εₙ+0.5εₙ₋₁。求γ(0)、γ(1)与本课离散谱。',['同一步两项不相关，γ(0)=1+0.5²=1.25。','相邻两项共享εₙ，γ(1)=0.5。','|k|>1时没有共享且噪声不相关，γ(k)=0。','f(ω)=[1.25+0.5e^(−iω)+0.5e^(iω)]/(2π)=(1.25+cosω)/(2π)。'],'γ(0)=1.25、γ(1)=0.5；f(ω)=(1.25+cosω)/(2π)。',['把连续时间谱的积分范围直接用于离散序列，重复计算无穷多个周期。','把二阶白噪声定义中的不相关自动升级为相互独立。'],'本课定义下，方差为σ²的离散白噪声谱密度是什么？',['σ²/(2π)，在[−π,π]上为常数','σ²cosω','只在ω=0有普通函数峰且其他全零','每个频率都等于一个观测值'],0,'白噪声协方差只有零滞后项，傅里叶求和只留常数σ²/(2π)，积分恢复方差。','离散谱按一个周期分配方差；“白”描述二阶频率分配，不是独立性的保证。')
  ]));
  chapters.push(C('time-series', 15, '时间序列分析', [
    ['15.1','平稳时间序列',['timeseries-white']],
    ['15.2','线性自回归滑动平均模型',['timeseries-ar','timeseries-maarma']],
    ['15.3','模型的应用',['timeseries-difference','timeseries-workflow']]
  ], [
    L('timeseries-white','时间序列与白噪声：有顺序的数据，不能当成散装样本',['时间序列','白噪声','自相关'],'区分一条序列与其概率模型，辨别不相关、独立和高斯白噪声。','平稳序列、协方差、样本与总体',[
      S('顺序本身就是数据的一部分', '十天的用电量如果排序后只剩一张直方图，你仍知道常见大小，却丢掉了连续高峰、周期与反弹。时间序列分析正是利用顺序关系：模型写为{Xₜ}，实际看到的是某次实现x₁到xₙ。相邻值有联系时，不能默认样本量n等于n份独立信息；也不能随意打乱训练测试顺序。平稳时间序列是离散时间平稳过程，均值、方差与时间差关联有稳定规则，但眼前有限一段仍可能出现随机的趋势片段。看图是模型诊断起点，不是平稳性的数学证明。'),
      S('白噪声是线性预测的基准', '本课二阶白噪声εₜ满足E[εₜ]=0、Var(εₜ)=σ²且t≠s时Cov(εₜ,εₛ)=0。它表示没有非零滞后的线性相关，不表示各时刻相互独立。若另说独立白噪声，就增加独立条件；若说高斯白噪声，要求联合高斯，此时零协方差可推出独立。不同教材对白噪声措辞可能稍异，题目给出的定义优先。实测残差样本自相关很小，也只说明未发现明显线性关联，不等于证明所有非线性依赖或波动聚集都不存在。'),
      S('一个零相关却有依赖的具体构造', '令Zₜ相互独立且服从标准正态，设εₜ=ZₜZₜ₋₁。每项均值0，方差1；相邻两项乘积中有独立零均值因子，因此协方差0，更远项也不相关，所以它是二阶白噪声。但相邻平方共同包含Zₜ²，E[εₜ²εₜ₊₁²]=E[Zₜ₋₁²]E[Zₜ⁴]E[Zₜ₊₁²]=3，而各平方期望都是1，平方的协方差为2。这显示两项不是独立。零线性相关并没有消除共同的随机幅度来源，用这个例子就能记住白噪声定义的边界。'),
      S('自相关图是估计，不是总体真相', '总体自相关ρ(k)=γ(k)/γ(0)，样本自相关则从有限数据估计，通常会随机偏离零。即使真实白噪声，许多滞后里也可能偶然出现几个突出点；同时观察很多滞后还涉及多重比较。计算前要说明是否去均值、采样间隔及缺失处理，不能用相隔不等的记录假装等间隔序列。做题先写模型条件，再推总体γ与ρ，最后才讨论样本图可能像什么；真实建模则把图、设计知识、残差和时序验证一起看，不靠一根越界柱就宣布发现必然规律。')
    ],'Zₜ独立标准正态，εₜ=ZₜZₜ₋₁。为什么它不相关却并非独立序列？',['E[εₜ]=0，E[εₜ²]=1。','相邻乘积含Zₜ₋₁、Zₜ₊₁等独立零均值因子，故协方差0。','相邻平方乘积期望为1×3×1=3。','因此Cov(εₜ²,εₜ₊₁²)=3−1=2；独立会使平方也独立，故这里不独立。'],'它是二阶白噪声，但有非线性依赖。',['看到白噪声就无条件当成独立同分布正态。','把有限样本的几根自相关柱当作总体相关函数的精确值。'],'二阶白噪声的定义必然保证哪一项？',['不同时刻协方差为零','不同时刻相互独立','每个时刻服从正态','任意非线性函数之间也不相关'],0,'白噪声定义给出零均值、恒方差和不相关。独立与联合高斯是额外条件。','顺序中可能藏着线性以外的联系；白噪声先是一种二阶描述。'),
    L('timeseries-ar','AR(1)：昨天留下多少，今天再添一点扰动',['AR模型','因果平稳','自回归'],'推导因果平稳AR(1)的均值、方差和相关衰减，并理解单位根边界。','平稳序列、几何级数、白噪声',[
      S('自回归就是让过去的自己参与预测', '把偏离长期均值的部分记为Yₜ=Xₜ−μ，最简单自回归模型是Yₜ=φYₜ₋₁+εₜ。φ决定昨天的偏离留下多少，εₜ是今天新增的零均值扰动。φ=0.5时，昨天高出均值4，今天在没有新扰动时预计仍高2；φ为负则倾向交替反弹。若原式写Xₜ=c+φXₜ₋₁+εₜ，平稳均值满足μ=c/(1−φ)，所以截距c通常不等于长期均值μ。把中心化和原始方程分开，能避免软件参数解释中的常见误读。'),
      S('为什么熟悉的因果平稳解要求|φ|<1', '不断代入前一时刻，有Yₜ=εₜ+φεₜ₋₁+φ²εₜ₋₂+…，过去扰动按几何权重逐渐变弱。|φ|<1时权重平方可求和，有限方差白噪声可形成这个仅依赖当前与过去扰动的因果平稳解。φ=1时得到随机游走，旧扰动不衰减，通常方差不断累积；不能再用平稳AR(1)公式。更一般存在利用未来噪声的非因果构造，因此严格措辞应是“通常采用的因果平稳AR(1)要求|φ|<1”，而不是对任何数学解无条件断言。初学先掌握因果版本即可。'),
      S('方差与相关从共享扰动而来', '若创新方差为σ²且与过去不相关，取方差有γ(0)=φ²γ(0)+σ²，得γ(0)=σ²/(1−φ²)。再把方程与Yₜ₋ₖ相乘取期望，可得γ(k)=φᵏγ(0)，ρ(k)=φ^|k|。正φ使相关逐渐衰减，负φ使符号交替。若φ很接近1，长期方差和记忆长度都可能很大，有限序列看起来像有趋势；把0.99粗略当成“和0.5一样都小于1”会漏掉实际差别。这里的总体相关公式不意味着样本自相关每个滞后都恰好落在同一条曲线上。'),
      S('预测要说清对新增扰动作了什么假设', '若εₜ独立于过去或至少对过去条件均值为零，那么h步条件均值预测为μ+φʰ(Xₜ−μ)。预测不是把未来真实轨迹定死，未来各步还会叠加新扰动，预测误差方差随h增长并趋于过程方差。仅说二阶白噪声通常足以讨论最佳线性预测，但要把它叫完整条件期望，应有相应创新条件。做题先写中心化式、检查|φ|、再算μ与γ；遇到预测，把“未来扰动均值为零”写出，能看清为何点预测逐渐回归长期均值，以及区间为何不会缩成一个点。')
    ],'Xₜ=2+0.5Xₜ₋₁+εₜ，创新方差3且独立于过去，求平稳均值、方差和二阶滞后协方差。',['|0.5|<1，存在通常的因果平稳解。','μ=2/(1−0.5)=4。','γ(0)=3/(1−0.25)=4。','γ(2)=0.5²×4=1。'],'均值4，方差4，滞后2协方差1。',['把原方程截距2直接当长期均值。','在φ=1的随机游走上仍套σ²/(1−φ²)并声称是有限平稳方差。'],'因果平稳AR(1)中，|φ|<1的直觉是什么？',['过去扰动的影响逐步衰减，平方权重可求和','创新从此不再随机','各时刻值完全独立','原方程截距必为零'],0,'几何衰减让无限过去的贡献形成有限方差；它并不会消除相关或随机性。','AR是对过去偏离的逐步遗忘；先找均值，再量记忆。'),
    L('timeseries-maarma','MA和ARMA：共享过去扰动，与共享过去观测不同',['MA','ARMA','可逆性','特征根'],'识别MA、ARMA方程与根的符号约定，分开因果平稳和可逆条件。','白噪声、AR模型、多项式与复数模的基本概念',[
      S('移动平均不是简单平滑数据的同义词', '统计模型MA(q)写成Yₜ=εₜ+θ₁εₜ₋₁+…+θqεₜ₋q，其中Y已减去固定均值。它组合的是不可直接观察的扰动，并不必等权，也不必权重和为1；与把最近几天观测取平均的平滑操作要区分。有限个平稳白噪声的线性组合自动宽平稳。MA(1)相邻两项共享一份噪声，因此γ(1)=θσ²，方差(1+θ²)σ²，超过一阶后无共享，协方差为零。这种有限滞后截断是模型的总体性质，样本自相关不会精确截成零。'),
      S('ARMA把两种记忆合在一个方程', '本课约定φ(B)Yₜ=θ(B)εₜ，B为后移算子，BYₜ=Yₜ₋₁；φ(z)=1−φ₁z−…−φpzᵖ，θ(z)=1+θ₁z+…+θqzq。AR部分使用过去的Y，MA部分使用过去的ε。正负号约定很重要：有的教材把MA系数写成减号，直接搬软件输出会反号。通常讨论无公共因子、参数可辨识的最简模型。ARMA(p,q)的p和q是两侧的阶数，不是样本量，也不是预测时只能看最近p或q个数据。因果展开可能依赖无限多过去扰动，只是影响逐渐减弱。'),
      S('两个根条件回答不同问题', '常用因果平稳ARMA要求AR多项式φ(z)的所有根都在单位圆外，即|z|>1；这样Y可由当前与过去噪声稳定构造。可逆性要求MA多项式θ(z)的根也在单位圆外，它让噪声能由当前与过去观测稳定恢复。有限MA即使不满足可逆性仍可平稳，所以不能把两个条件混为一谈。MA(1)在本加号约定下根为−1/θ，可逆对应|θ|<1。AR(1)根为1/φ，因果平稳对应|φ|<1；记成“根在圆外”，不等于把系数本身也要求在圆外。'),
      S('用可计算小模型核对你读的符号', '对Yₜ−0.5Yₜ₋₁=εₜ+0.4εₜ₋₁，AR根是2，MA根是−2.5，都在单位圆外，符合因果平稳和可逆条件。若把0.4改为2，有限MA部分仍可生成有限方差扰动，整体AR稳定也仍能得到因果平稳过程，但这个参数化不再可逆。拟合时需区分可辨识参数化与模型预测表现，不能仅因为方程能运行就断言估计唯一可靠。做题按“先写多项式→求根→看模→分别回答两个条件”，比记住一串易混的正负号稳妥。')
    ],'模型Yₜ−0.5Yₜ₋₁=εₜ+0.4εₜ₋₁，按本课约定判断因果平稳与可逆。',['写φ(z)=1−0.5z，根z=2。','写θ(z)=1+0.4z，根z=−2.5。','两个根的模分别2和2.5，都大于1。','AR条件给通常因果平稳解，MA条件给可逆性，两者分别成立。'],'该ARMA(1,1)参数化因果平稳且可逆。',['把系数|φ|<1误记成多项式根模小于1；两者方向相反。','认为MA不可逆就一定不平稳；可逆性与平稳是不同要求。'],'MA(1):Yₜ=εₜ+θεₜ₋₁中，可逆性要求什么？',['|θ|<1','|θ|>1才可能平稳','θ必须为正','θ必须等于1'],0,'本加号约定的MA多项式根为−1/θ，根在单位圆外对应|θ|<1；θ=0为白噪声，可逆。','AR根控制因果平稳，MA根控制可逆；符号约定写在第一行。'),
    L('timeseries-difference','差分与ARIMA：把累积变化拆开，也要记得接回去',['差分','ARIMA','单位根'],'理解差分的目的、还原预测的方法以及过度差分的代价。','平稳序列、ARMA、均值与趋势',[
      S('不断累积的水平，与每天新增的变化', '银行余额、累计访问量或某些价格水平可能持续变化，原序列不适合直接用固定均值的平稳模型。差分ΔXₜ=Xₜ−Xₜ₋₁改问“这一期增加多少”。随机游走Xₜ=Xₜ₋₁+εₜ原水平方差随时间增长，而一阶差分恰为εₜ，可以平稳。若还有固定漂移d，则差分均值为d，未必为零。差分不是把数据变成正确答案的万能动作，而是针对某种累积非平稳结构的处理；季节波动、确定趋势和方差变化可能需要不同办法。'),
      S('ARIMA的中间那个数记录差分次数', 'ARIMA(p,d,q)表示先对原序列做d次普通差分，再用ARMA(p,q)描述差分后的序列。d=0就回到ARMA。后移算子可写(1−B)Xₜ=ΔXₜ，多次差分对应(1−B)ᵈ。若每十二个月有季节结构，可考虑季节差分Xₜ−Xₜ₋₁₂，但这与普通差分不是同一符号，模型需明确写出季节周期。即使软件允许自动选阶，也应先看采样间隔、趋势和研究背景；差分次数过高会放大高频噪声并引入不必要的负相关。'),
      S('确定趋势与随机趋势不是一回事', '若Xₜ=a+bt+uₜ而uₜ平稳，可以拟合确定直线后研究残差；若Xₜ是随机游走，未来冲击永久留在水平里，仅减去一条固定直线通常不能消除这种累积随机性。两者短样本图像都可能向上，靠肉眼很难完全区分，应结合模型、诊断及适当检验。过度差分同样有结构后果：对本来独立方差σ²的白噪声作一阶差分，得到εₜ−εₜ₋₁，方差2σ²、邻接协方差−σ²，不再是独立序列。处理“更多”不等于更稳健，每一步应有目标。'),
      S('预测变化后，要把水平和不确定性接回去', '若在时刻T观测X_T=100，模型预测未来两步差分分别2与3，水平点预测就是102、105，而不是把两差分直接当未来水平。若为带漂移随机游走且未来独立创新方差4，h步预测误差是h个创新之和，方差4h，标准差2√h，随时间增长。一般模型还需处理参数估计、差分还原和误差相关，不能把各步区间端点简单逐项相加当作正确区间。做题先明确模型是在水平还是差分上，再写还原递推，最后计算误差协方差；这能避免预报数字虽漂亮却放错尺度。')
    ],'带漂移随机游走Xₜ=Xₜ₋₁+2+εₜ，创新独立、均值0方差4。现X_T=100，求两步预测与误差标准差。',['差分ΔXₜ=2+εₜ，均值为2。','两步水平预测为100+2×2=104。','两步误差ε_T₊₁+ε_T₊₂，独立使方差4+4=8。','标准差√8=2√2≈2.828。'],'两步点预测104，预测误差标准差2√2；未计参数估计不确定性。',['对所有时间序列反复差分到看起来平就停止，却不检查过度差分。','把差分的预测值直接当成原水平的预测值。'],'ARIMA(p,d,q)里的d通常表示什么？',['普通差分次数','观测数据个数','任何季节的固定长度','AR系数必须等于的数'],0,'p、q分别是差分后AR与MA阶数，d记录为了该建模流程使用的普通差分次数。','先问数据是水平还是变化；差分把累积拆开，预测时还要接回原尺度。'),
    L('timeseries-workflow','建模到预测：让模型只看当时真正知道的信息',['时序验证','残差诊断','预测误差'],'建立不偷看未来的分析流程，理解诊断与外推的实际边界。','ARMA或ARIMA、训练测试、残差、自相关',[
      S('时间顺序是一条不能偷越的边界', '假设有一百天数据，想知道模型能否预测未来，就应在前面的日子训练，把后面的日子留作验证。随机打散后分八十天训练、二十天测试，会让模型接触测试日期之后的信息，评估问题已不再是现实中的预测。即使模型只用过去滞后，标准化、补缺失、趋势估计或选阶若用整段数据，也可能把未来泄露进去。正确的问题是“站在那一天，我能知道什么”，所有预处理和参数选择都应遵守同一时间边界。'),
      S('一个清晰工作流程比一次自动拟合更可靠', '先确认采样间隔、单位和观测机制，画时序图检查缺失、异常、季节性与结构变化；再在训练段内选择变换、差分和候选模型。ACF与PACF可给阶数线索，但样本误差与混合结构会让图形不典型，不应当作唯一裁判。拟合后看残差是否仍有均值趋势、线性相关或波动聚集，并比较合理的简单基线，例如最后值预测、季节性最后值预测。模型越复杂越能贴合训练数据，不保证预测越好；信息准则提供一种权衡，也不能替代真正面向未来的验证。'),
      S('滚动评估如何模拟每天真的做预测', '选一个初始训练窗口，先只用它预测下一天；揭开这一天真值后再扩展训练或按固定窗滚动，继续预测下一天。每次模型只使用已经发生的数据，误差来自一串真实的“当时未知”。按目标选择MAE、MSE等指标，还要看不同预测步长和异常时期表现，不能只挑最好的一段。拟合残差与真正的样本外预测误差不同，前者常因参数已用同一数据估过而偏乐观。预测区间需要额外说明创新、模型和参数的不确定性，不能把一个训练集R²替代未来可靠度。'),
      S('诊断通过，是暂未发现问题而非证明真模型', '残差相关不显著，只表示在选定检验和样本量下没有发现相应线性结构，不证明独立、正态或模型真实。检验也有功效和多重比较问题。若环境换制度、设备换型号或出现突发冲击，历史平稳模式可能失效；应记录适用时期，持续监测而非承诺永久有效。做题报告可按数据与设计、模型方程与条件、估计结果、诊断、时序验证、预测及限制这条线展开。这样读者能清楚知道哪部分是观察、哪部分是假设、哪部分是预测，不会被一张平滑拟合图掩盖信息边界。')
    ],'有按时间排列的100天数据，计划前80天训练、后20天测试。均值标准化和缺失填补应怎样做？',['先固定时间边界：训练1—80天，测试81—100天。','标准化均值和尺度只用训练段估计，再应用到测试段。','缺失填补遵守预测时可用信息，不能用尚未发生的未来观测反向补值。','模型选择在训练内或更早的滚动验证进行，最终测试不反复调参。'],'所有估计和预处理都遵守时间可见性；测试段用于评估已确定流程。',['先对全100天标准化再划分，认为只是预处理所以不算泄漏。','看到残差无显著自相关，就断言真实误差独立且模型永久有效。'],'哪项最符合面向未来的时间序列评估？',['前段训练、后段评估，预处理只用当时可知数据','随机打散日期后让训练包含未来','先看全部测试结果再反复选最佳模型','只报告训练误差，不比较未来误差'],0,'时序预测必须模拟真实信息边界，未来数据不能参与当时的估计、预处理或选择。','好的预测先守住时间边界，再讨论模型有多精巧。')
  ]));
  chapters.push(C('r', 11, '在数理统计中应用R软件', [
    ['11.1','概述',['r-basics']], ['11.2','箱线图',['r-boxplot']], ['11.3','假设检验',['r-test']],
    ['11.4','方差分析',['r-anova']], ['11.5','线性回归',['r-regression']], ['11.6','bootstrap方法',['r-bootstrap']]
  ], [
    L('r-basics','R代码不必整段背：数据、动作、结果三层读',['R','向量','数据框'], '读懂最小R脚本，并知道软件不会代替抽样和建模判断。','平均数、样本标准差；不要求编程基础',[
      S('把一段程序看成一张计算草稿', '统计软件最适合替你反复算数，最不适合替你决定数据代表谁。开始时不要被英文吓住：给一串数起名字，对它做一个明确动作，再查看结果，这就是最短工作流程。R中的x可以看作写着“本次重量”的盒子，盒里装一整列数，而不只是一个数。mean(x)的括号像把盒子交给一个叫“平均”的工具。代码有时比手算短得多，但应该先用三四个数算一遍已知答案；这样你才能检查数据是否读反、单位是否混用、缺失值是否被误作零。'),
      S('从左箭头、向量和下标开始', 'x <- c(2,4,6,8)读作“把这些数合成一列，保存为x”。左箭头是赋值，不是比较，也不是数学中左右对称的等式。c是连接成向量的函数名，逗号分隔各个数。R的第一个元素用x[1]访问，和C从零开始的数组下标不同。length(x)问有多少个元素，mean(x)问算术平均，sd(x)算分母为n−1的样本标准差。若返回NA，先查是否存在缺失；na.rm=TRUE会删除缺失后再计算，却不证明这种删除没有选择偏差。看懂动作比记住一个结果更重要。'),
      S('对象能保存的不只有数字', '统计函数往往返回一个带名称的结果集合，例如检验对象含统计量、p值、区间等。先把返回值保存，再打印或提取需要的部分，能避免每次重新计算。数据框data.frame像一张表，每一行应对应同一个观察单位，每一列是一个变量；若把不同人的年龄和体重错位，即使代码运行成功，相关与回归也会失去意义。字符引号用于文字标签，数值不应为图方便全加引号。报错信息往往在告诉你对象不存在、类型不合适或长度不一致，先定位这一层，再回到统计意义。'),
      S('代码可以复现，不代表结论必然正确', '本章例子只需R自带的基础功能，网页提供代码点读，不会在浏览器执行R。把代码复制到自己安装的R环境后，可逐行运行、观察对象，再改一个数字比较变化。涉及模拟时记录种子、R版本及随机数设置；相同种子在不同版本或随机数算法下不保证逐位相同。报告还应记录变量含义、样本来源、缺失处理和模型条件。练习顺序是先解释输入和输出的单位，再验证小例子的手算答案，最后才扩大数据规模；一个绿色的“运行成功”只证明语法被接受。')
    ],'用R处理2、4、6、8：样本量、均值、样本标准差分别应是多少？',['先把四个观测保存为向量x。','length(x)=4，确认未漏掉或多读一个值。','均值为20/4=5。','平方离差和为9+1+1+9=20，样本标准差为√(20/3)≈2.582。'],'样本量4，均值5，样本标准差约2.582。',['以为R下标和C一样从0开始；x[1]才是首元素。','把运行成功等同于抽样合理；程序不会自动检查研究对象是否有代表性。'],'R表达式mean(x)最直接的含义是？',['对x中的数计算算术平均','把x改成全部相等的数','计算x的元素个数','判断总体是否正态'],0,'mean是对给定数据求均值的动作；它既不检验分布，也不会改变原观测。','先说清输入、动作和输出，再看程序怎样拼写。',{level:'入门', code:R('x <- c(2, 4, 6, 8)\nlength(x)\nmean(x)\nsd(x)','确定性小例子：应输出4、5和约2.582。sd使用n−1分母。',['把四个观测连接成向量，赋值给x；左箭头表示保存。','数x里有多少个元素，得到4。','求x的算术平均，得到5。','求样本标准差，得到约2.582；不是标准误。'])}),
    L('r-boxplot','箱线图：先看中间的人，再追问远处的点',['箱线图','四分位数','异常值'], '解释箱体、须和远点的规则，避免把远点自动当成错误数据。','中位数、分位数、四分位距',[
      S('为什么不只画一个平均数', '五个人的等待时间为1、2、3、4、20分钟，平均数是6，典型等待却明显没有那么久。箱线图把排序后的中间位置、中央一半的范围和远端观测一起展示，能让你迅速看见偏斜与潜在异常。它不是完整分布图：两个形状很不同的分布也可能有相同箱体。数据很少时最好同时画出原始点，数据很多时可补直方图；先看图再计算，可以发现把秒误记成分钟、重复录入或分组混乱等问题。图形用于提出调查问题，不能独自替代统计推断。'),
      S('箱、须、远点各自是一种规则', '箱体上下边对应下、上铰链，接近第一和第三四分位数，箱内横线通常是中位数。R默认箱线图的铰链与quantile默认分位数算法在某些小样本大小下可能不同，不能混用公式后怪图画错。四分位距IQR是箱长。默认须延到仍处于箱边外1.5倍箱长以内的最远观测，而不是一定落在理论界限，也不是无条件伸到最小最大值。越过界限的观测单独画成点，它只是“按这个描述规则较远”，并不自动等于记录错误或不可能事件。'),
      S('对偏斜与分组保持敏感', '右边须更长、右侧远点更多，常提示右偏，但须长短不是正态性检验的充分依据。工资、住院天数等本就可能有长右尾，真实远点恰恰携带重要信息；删掉它们会改变目标总体。比较两组箱体时也要看单位、样本量与采样方式，两个中位数有高低并不自动意味着总体差异显著。若要进一步检验，应按配对、独立组或其他设计选择方法。不能先只保留符合预期的图，再把图上“看起来不对”的人删除后继续声称随机样本。'),
      S('把一个点追溯成一条观察记录', '做题按顺序排序、求中间位置、计算箱长、写出界限、再找界限内的最远观测。真实分析中，给远点加一个“待核对”标签，查原始测量、单位和观察条件；确认是有效观测就保留，并可报告稳健指标或敏感性分析。下面的R脚本既画图又打印图形统计量，你能把数值与图上的部件对应起来。R输出的$stats依次记录下须、下铰链、中位数、上铰链、上须；$out列出按规则标记的远点。记住“描述规则”四字，就不容易把画图软件当成删数据裁判。')
    ],'数据1、2、3、4、20按R默认箱线图规则，须和远点怎样确定？',['本例下铰链2、中位数3、上铰链4。','箱长为4−2=2，界限为2−3=−1与4+3=7。','界限内最远观测是1和4，所以须到1和4。','20在上界7之外，被标记为远点，需核对原因而非自动删除。'],'五数图形统计量为(1,2,3,4,4)，远点为20。',['以为须必然延到最小和最大观测；默认1.5倍箱长规则会把远点另画。','把箱线图标出的点自动判成录入错误。'],'箱线图把某个观测单独画成远点，首先意味着什么？',['它超过了所采用的箱线图距离规则','它必然是错误数据','它的发生概率严格为零','必须删除后才能分析'],0,'远点是描述规则的标记，可能是错误，也可能是真实长尾或特殊个体，需回查测量。','远点是问题的起点，不是删除的许可证。',{code:R('x <- c(1, 2, 3, 4, 20)\nboxplot(x, horizontal = TRUE)\nboxplot.stats(x)$stats\nboxplot.stats(x)$out','默认须规则coef=1.5；此例铰链为2与4，远点20。',['保存五次等待时间。','画水平箱线图；横轴单位应由研究者说明。','提取下须、下铰链、中位数、上铰链、上须。','提取按图形规则标记的远点；标记不等于应删除。'])}),
    L('r-test','读t.test输出：别只盯着最后一个p值',['R','t检验','配对设计'], '把检验方向、原假设、统计量、置信区间和研究设计对应起来。','t检验、p值、置信区间',[
      S('先向自己说明“检验谁”', '若一批称量值是9、10、11、12，你想检验总体均值是否为10，就要明确总体、独立样本与测量单位；不是输入一串数字后让软件替你找问题。单样本t检验以(样本均值−假设均值)除以估计标准误。正态独立样本下，它具有精确的t参考分布；非正态时可能依赖大样本近似，对严重偏斜和异常值要更谨慎。R的mu指定被检验的均值或均值差，alternative指定双侧、较大或较小。研究方向应在看数据前确定，不能看见均值偏高才把双侧改成单侧。'),
      S('每一行输出都在回答不同问题', 'estimate给观测数据的点估计；statistic给标准化后的差异；parameter通常是自由度；p.value是在假设成立时观察到至少如此极端统计量的尾部概率；conf.int给所选方向与置信水平对应的均值或均值差区间。标准误衡量点估计的波动，不是个体散布。即使p很小，也要看差异大小和区间是否具有实际意义；即使p不小，也不是证明总体均值恰等于假设值。输出中的方法名称也值得看，它提醒你软件究竟运行了单样本、Welch两样本还是配对检验。'),
      S('两列数据首先是设计问题', '同一批人服药前后的测量属于配对，应对同一人的差值建模；两批不同人的数据通常是独立组。把配对数据错当独立组会丢掉配对结构，把独立组硬配对也会制造虚构关系。R两样本t.test默认var.equal=FALSE，使用Welch方法，不默认假定方差相等；要用合并方差方法需明确条件和设置。paired=TRUE时必须保证两列一一对应。软件能检查长度，却不知道第一行究竟是不是同一个人，因此数据整理的责任仍在你。'),
      S('先用手算建立输出的锚点', '下面小例子的均值为10.5，样本方差为5/3，标准误为√(5/12)，所以t约为0.775，自由度为3。手算这几个数后再看软件，你就能识别mu写成0、遗漏观测、把标准差误当标准误等错误。代码只提取四个重要部分，而不是把所有输出当作天书。真实报告应写均值差及单位、区间、检验方法和条件，附上p值作为证据的一部分。数据量很少时检验能力有限，未拒绝原假设尤其不等于发现“没有效应”；还可能只是信息不足。')
    ],'对9、10、11、12作双侧检验H₀:μ=10，先手算t统计量。',['均值(9+10+11+12)/4=10.5。','平方离差和为5，样本方差s²=5/3。','均值标准误s/√4=√(5/12)。','t=(10.5−10)/√(5/12)=√(3/5)≈0.775，自由度3。'],'t≈0.775，自由度3；不能仅凭未拒绝就断言总体均值等于10。',['用paired=TRUE来“提高显著性”，却没有真实配对设计。','认为R两独立组t检验默认合并方差；默认是Welch方法。'],'对同一批人的治疗前后指标，最先需要确定什么？',['两列是否按同一人正确配对','哪种设置能让p值最小','是否可以把所有负差删掉','是否让两列均值看起来相等'],0,'统计方法应服从研究设计。配对顺序决定差值的意义，不能按结果反过来挑设计。','先定研究问题与设计，再让软件替你计算。',{code:R('x <- c(9, 10, 11, 12)\nfit <- t.test(x, mu = 10, alternative = "two.sided")\nfit$statistic\nfit$conf.int\nfit$p.value','独立正态样本的单样本t检验小例子；此处不把p值解释成原假设概率。',['输入四次测量。','以均值10为零假设，做双侧单样本t检验并保存结果。','查看t统计量；约0.775，自由度可另用fit$parameter查看。','查看总体均值的默认95%双侧置信区间。','查看双侧p值；它不是H₀为真的概率。'])}),
    L('r-anova','方差分析表：把总波动拆开再比较',['R','ANOVA','组间组内'], '把R表中的平方和、自由度、均方和F连回组间差异。','单因素方差分析、平方和、F检验',[
      S('名字叫方差分析，问题却常是均值', '三种教学方式的成绩平均数不同，可能是方法真的有差别，也可能只是每组学生本来就有波动。单因素方差分析把数据相对总均值的起伏，拆成组均值之间的起伏与同组个体之间的起伏。组间差异要以组内噪声为尺子，才知道是否大到难以用共同均值解释。经典模型假设误差独立、各组正态且方差相同；随机分配或合理抽样是理解独立和因果的基础。软件不会因为一张漂亮的F表就补上这些设计条件。'),
      S('在公式中把组号声明成类别', 'R里y ~ group读作“用组别解释响应y”，波浪线是建模公式的分隔符，并非近似相等。group应是因子factor，明确A、B、C是类别。若把组号写成数值1、2、3并当连续变量，可能拟合的是随组号直线变化的回归，和允许各组有任意均值并不相同。aov生成模型对象，summary整理方差分析表。表中Df为自由度，Sum Sq为平方和，Mean Sq是平方和除自由度，F value是组间均方除组内均方，Pr(>F)是右尾p值。先解释每个量的角色，再去背英文缩写。'),
      S('整体拒绝之后，不能随口指出谁不同', 'H₀是所有组总体均值相等；拒绝它只表明至少有一组不同，不说明每一对都不同，更不自动说最大样本均值那组最好。若需要两两比较，应采用适合的事后比较或预先规划的对比，并考虑多重检验；反复做普通t检验会增加总体误报机会。与此同时要报告组均值、样本量和实际差异，不要仅以显著与否排序。若方差严重不等、数据有依赖或异常值，需检查设计、变换或合适替代方法；F检验的名字不能保证它对所有问题都稳健。'),
      S('用六个数把表重新算出来', '三组分别取(1,3)、(3,5)、(5,7)，组均值为2、4、6，总均值为4。组间平方和为2×[(2−4)²+(4−4)²+(6−4)²]=16，自由度2；组内每组平方离差和都是2，合计6，自由度3。因此组间均方8、组内均方2，F=4。这个例子只为让表中的数有来处；每组两个人很难检查分布条件。你可以在R中核对F和自由度，然后改动组内散布：组均值不变但噪声增大，F就会变小，直观看到证据强度依赖信号与噪声的相对比例。')
    ],'三组(1,3)、(3,5)、(5,7)，求单因素ANOVA的F值。',['组均值2、4、6，总均值4。','组间平方和16，组间自由度3−1=2，均方8。','组内平方和6，组内自由度6−3=3，均方2。','F=8/2=4，参考自由度为(2,3)。'],'F=4，自由度(2,3)，整体检验不定位具体差异组。',['用数值组号代替factor，却以为一定做了任意组均值比较。','拒绝所有均值相等后断言每一对均值都不同。'],'ANOVA拒绝“所有组总体均值相等”能直接推出什么？',['至少一组总体均值不同','每一对总体均值都不同','样本均值最大的组必然最好','各组方差必然不同'],0,'整体备择是并非所有均值相同；具体哪一组、哪一对需要额外比较与误差控制。','读F表时同时看分解、条件和结论范围。',{code:R('y <- c(1, 3, 3, 5, 5, 7)\ngroup <- factor(c("A", "A", "B", "B", "C", "C"))\nfit <- aov(y ~ group)\nsummary(fit)','经典单因素模型；应得到组间均方8、残差均方2和F=4。',['保存六个响应，顺序要与组别一致。','把A、B、C明确声明为三个类别，每组两人。','以组别解释响应，拟合单因素方差分析模型。','打印平方和、自由度、均方、F值和整体p值。'])}),
    L('r-regression','回归软件里的直线：系数、残差和预测对象',['R','线性回归','预测'], '区分拟合均值、个体预测与因果结论，读懂最小回归脚本。','最小二乘、一元线性回归、残差',[
      S('直线是在概括平均关系', '每天学习时长x与测验得分y往往有关系，但同样学习两小时的人分数不会完全相同。回归直线试图概括给定x时y的平均变化，把剩余差异交给误差。最小二乘挑选截距与斜率，让观测值到拟合值的竖直残差平方和最小。它并非让每一个点都在直线上，也不是使所有方向的距离最小。斜率单位是“y单位/x单位”；若把小时换成分钟，斜率数字会改变，但对同一现实情形的预测应保持一致。先理解单位，很多系数误读会自然消失。'),
      S('从模型对象里取出你真正关心的量', 'lm(y ~ x)默认含截距，返回的coef依次给截距与斜率；fitted给每个观测x处的拟合均值；residuals给实际y减拟合值。summary还提供标准误、t检验、残差尺度和R²等信息。R²较高说明样本中解释的变异比例较高，不代表模型形式正确或有因果效果。显著的斜率也可能来自共同趋势、遗漏变量或反向作用。若要作推断，经典标准误还依赖误差条件；画残差对拟合值图能检查弯曲、异方差等线索，但没有明显图形也不是充分证明。'),
      S('预测均值与预测一个人不是同一件事', '给x=4时，直线上的ŷ是总体条件均值的估计。平均关系本身有估计误差，因此可以造均值的置信区间；新来一个人的y还带个体噪声，所以预测区间通常更宽。R的predict中interval="confidence"与interval="prediction"分别对应这些问题，必须先说清要预测谁。把三名学生的关系外推到每天学习二十小时尤其危险：样本范围外模型形状没有被验证。软件照样能返回一个数字，数字可算不等于结论可靠，这在回归中比在单纯算均值时更容易被忽略。'),
      S('用小样本亲手找出那条线', '取x=(1,2,3)，y=(2,3,5)，x均值2，y均值10/3。横向平方离差和Sxx=2，交叉离差和Sxy=3，故斜率3/2，截距1/3。x=4时拟合值为19/3。这组数据很少，只有一个残差自由度，适合读代码而不适合宣称发现普遍规律。下面脚本只打印系数、残差与一个点预测；不隐藏小样本的不确定性。你可以先手算三点残差，再核对软件，它们应相加为零，因为这里使用了带截距的普通最小二乘，而非任何回归算法都天然满足这个性质。')
    ],'x=(1,2,3)、y=(2,3,5)，求拟合直线及x=4时的拟合值。',['x̄=2，ȳ=10/3，Sxx=1+0+1=2。','Sxy=(−1)(−4/3)+0+(1)(5/3)=3。','斜率b=3/2，截距a=10/3−3=1/3。','代入x=4，ŷ=1/3+6=19/3≈6.333。'],'ŷ=1/3+(3/2)x，x=4时为19/3；这是模型均值预测，不保证新个体恰为此值。',['把回归相关自动解释为改变x会导致y改变。','把均值置信区间当作新个体预测区间。'],'同一x处，通常哪种区间还需要包含新个体的额外噪声？',['个体预测区间','回归均值的置信区间','仅截距的估计值','仅样本量这一数字'],0,'新个体在平均关系附近仍会波动，因此预测区间除了参数估计不确定性，还要包含个体误差。','软件能给出直线；你要给直线补上单位、适用范围和不确定性。',{code:R('x <- c(1, 2, 3)\ny <- c(2, 3, 5)\nfit <- lm(y ~ x)\ncoef(fit)\nresiduals(fit)\npredict(fit, newdata = data.frame(x = 4))','带截距的一元最小二乘；系数应为1/3与3/2，点预测19/3。',['保存自变量，三个位置对应三次观察。','保存同顺序响应，不能打乱配对。','用默认带截距的直线拟合y对x的关系。','提取截距和斜率，注意单位不同。','提取实际y减拟合y的残差。','传入名为x的新数据框，求x=4处的点预测；此行未计算区间。'])}),
    L('r-bootstrap','在R中重抽样：每个括号都对应一次统计动作',['R','bootstrap','可复现模拟'], '读懂有放回抽样和重复计算的嵌套，并识别程序模拟的范围。','经验分布、自助标准误、百分位区间、R向量',[
      S('先把嵌套括号拆成中文', 'mean(sample(x,length(x),replace=TRUE))看上去很长，其实从内向外只有三个动作：数出原样本有几个观测，按这个数量从原观测有放回重抽，最后求这份新样本的均值。外面再包一层replicate(B,…)就是把这串动作重复B次，把B个均值存起来。抽签时选的是原样本的位置；两个不同位置数值相同，也仍然是两张签。对初学者来说，先用三次重复并打印每份样本，比盲目复制一万次更有帮助。看懂一次后，再让电脑承担重复劳动。'),
      S('种子负责复现，次数负责模拟精度', 'set.seed给随机数生成流程设一个可记录的起点，便于在同版本和相同随机数设置下复查；它不使数据更真实，也不使抽样更独立。不同R版本或算法设置可能改变序列，因此严谨复现还应记录sessionInfo或R.version.string等环境信息。B越大，同一个经验分布下的标准差和分位数通常越稳定，但不会增加原始样本量。运行一次得到某个端点，不应把它当作数学常数。通过改变B、重复检查和比较适用理论结果，你能区分电脑的随机抖动与统计问题本身的不确定性。'),
      S('用精确小计算检查模拟有没有跑偏', '下面样本为2、4、6、8，经验均值是5，经验总体方差使用1/n分母，等于5。自助世界中一次样本仍抽四个且独立，所以星号均值的条件方差为5/4，标准差√1.25≈1.118。大量重抽样得到的sd(b)应靠近这个值，而不是原样本标准差2.582。原均值常见的s/√n约为1.291；两者有限样本下不同，是经验方差分母与抽样方差修正的差别，不说明代码坏了。这个小例子让你能用理论锚点判断程序究竟在估计什么。'),
      S('输出是带条件的答案，不是万能按钮', '脚本末尾quantile取星号均值的2.5%和97.5%分位数，演示百分位区间；它没有自动验证独立同分布、没有修复偏差，也没有处理极端统计量的失效。若目的是假设检验，必须另行构造零假设生成机制，不能把这段未经中心化的区间代码直接改个名字。网页只展示与解释脚本，不提供R运行器；真实运行时先检查输入缺失、单位和目标统计量。保存原始数据、脚本、种子、环境与方法说明，比只保存一张模拟直方图更能帮助未来复核。')
    ],'x=(2,4,6,8)时，普通自助均值分布的条件标准差理论上是多少？',['经验均值是5。','经验分布方差为[(2−5)²+(4−5)²+(6−5)²+(8−5)²]/4=5。','每次从经验分布独立抽4个，均值条件方差为5/4。','条件标准差为√(5/4)≈1.118，足够多模拟的sd应在它附近。'],'约1.118；模拟结果会有有限B的随机误差。',['把replace=TRUE漏掉，结果均值始终为5却误以为估计非常精确。','认为设定种子就能保证任何R版本的输出逐位相同。'],'R中对完整原样本无放回抽同样数量后求均值，会发生什么？',['每次均值都等于原均值','每次都生成新的总体信息','均值一定趋近零','自动构成零假设分布'],0,'全部元素只是被重新排列，均值不会变化，因而不能模拟重新采样的均值波动。','把每层括号翻译成一个动作，重抽样代码就能逐步读懂。',{code:R('x <- c(2, 4, 6, 8)\nset.seed(2026)\nB <- 2000\nb <- replicate(B, mean(sample(x, length(x), replace = TRUE)))\nsd(b)\nquantile(b, c(0.025, 0.975))','独立同分布样本的教学示例；随机种子不保证跨R版本完全相同。区间是近似百分位法，不是精确保证。',['保存四个原始观测。','设置模拟起点，便于同一环境复查；不会增加真实信息。','设定重抽样次数2000，原始样本量仍为4。','每次有放回抽4个，再取均值；重复B次，得到B个自助均值。','计算这些自助均值的样本标准差，估计自助世界的标准误。','取2.5%与97.5%分位数，演示百分位区间；须另检查适用条件。'])})
  ]));
  const readingNotes = {
    'bootstrap-world': ['把重抽样亲手演一次', '拿三张纸分别写上第一包、第二包、第三包，每抽一张记录重量后放回，再抽下一张。若两包恰好同重，也不要合并纸签：经验分布的权重来自观测次数。完成一份三次抽签后只保留一个均值，再开始下一份。你会发现“数据点”“一份样本”“一个统计量”是三个层次。能够用纸签解释每一步，就已经掌握算法；电脑只是把这套纸上操作做得更快。'],
    'bootstrap-interval': ['用单位识别你正在估计哪种波动', '若重量以克计，个体标准差、均值标准误和区间端点都以克计，方差则以平方克计。但相同单位并不表示它们回答同一问题：个体散布不会因只改变均值计算中的样本量就自然消失，均值标准误却通常随独立样本量增大而减小。看到一项非常小的数，先问它属于哪一层，不要立刻夸测量精准。可以分别画原观测与自助均值的直方图，比较两幅图在描述谁。'],
    'bootstrap-parametric': ['把模型假设主动摆在桌面上', '若真实等待来自两个不同速率时段混合，用一个指数分布拟合就可能掩盖高峰。参数自助法会忠实地重复“单一速率”的假设，并不会通过重复自动发现时段混合。你可以先按业务时段画图，比较合理的不同模型，再观察标准误结论是否敏感。这不是要求永远找到完美分布，而是让结果的依赖条件可见。报告时说“在指数模型下的自助估计”，比只说“电脑算出来”更诚实也更有信息。'],
    'bootstrap-null': ['把零假设写成生成机制', '检验之前不妨问一句：如果有人只把零假设交给你，你是否能说明模拟样本如何生成？若答案仍是“直接照原数据抽”，就需要检查原数据的经验参数是否已偏离零假设。生成机制还要保留与研究设计有关的结构，例如配对关系或组间差异所受的约束。对复杂假设，零假设可能包含尚未知的干扰参数，需要在约束下估计。不要让一个中心化技巧代替所有问题的理论判断。'],
    'bootstrap-limits': ['让失败例子变成日常检查', '遇到零事故、样本最大值或极端分位数，先问自助世界能否产生影响结论的新情况；遇到同一个人的多次测量，先问重抽单位应是个人还是单次读数。若单位选错，抽出的数再多也没有对应真实重复实验。把这些问题写在脚本前几行的注释里，能提醒自己模拟在模仿什么，也让别人能够检查你是否保留了原研究的抽样结构。'],
    'r-basics': ['遇到报错时先缩成最小例子', '把一千行数据暂时换成三个已知数，把长函数拆成几个有名字的中间结果，每一步打印后再继续。若连样本量和均值都不符合手算，先检查读入、类型和缺失，而不是马上换统计方法。对象名区分大小写，修改代码后还要重新运行相关行，否则工作区里可能残留旧结果。把脚本按从头到尾顺序运行一次，是确认它不依赖偶然操作历史的简单办法。'],
    'r-boxplot': ['保留远点理由的记录', '如果核查发现二十分钟来自真实的紧急事件，它可能正是研究等待风险最重要的记录；如果发现原表写的是二十秒，则应纠正单位并留下依据。两种情况都可能画成远点，图形本身无法区分。还可以同时报告含全部有效观测的结果与合适的稳健描述，展示尾部对平均的影响。删数据的决定要有测量或设计理由，而不能只因为删后图更对称、检验更显著。'],
    'r-test': ['把输出翻译成一段能审查的话', '试着写出“在何种抽样与分布条件下，对哪个总体均值作何种方向检验，观察均值和假设值相差多少单位，区间大约多宽”。最后才附上尾部概率。这样的句子把证据和结论范围连接起来，也会暴露你是否遗漏配对设计、选错单位或把总体参数与样本结果混淆。若想检验差异小到可以忽略，通常需要等效性等另一个明确问题；普通未拒绝不提供这个保证。'],
    'r-anova': ['想象把每一组的噪声放大', '保持三个组均值二、四、六不变，把各观测离本组均值的距离都乘二。组间平方和没有改变，组内平方和会乘四，因而均方误差也乘四，原来的F值就变为四分之一。这说明均值差同样大时，个体噪声越强，证据越弱。你可以按这个规则在纸上改出新数据，再用软件核对。这样的控制变量小实验，比只记住表格中F在某一列更容易理解信号与噪声的比值。'],
    'r-regression': ['让残差给直线提问题', '把每个残差画在对应的自变量位置，若左右两端多为正而中间多为负，可能暗示弯曲关系；若散布随自变量增大，可能暗示方差不恒定；若按时间成串正负，可能有序列依赖。这些图形不是自动判决，但会指导进一步检查。不要为了让残差看起来漂亮而不断试模型后只报告最好的一次，模型探索和最终验证最好分开，否则显著性与预测能力都容易被高估。'],
    'r-bootstrap': ['对照两个标准差确认层次', '先打印sd(x)，再打印sd(b)：前者的对象是四个真实观测，后者的对象是两千个替身均值。虽然都调用sd，含义完全不同。若把统计量换成中位数，代码只改最内层mean为median，但是否有效仍需重新检查，不是所有目标都继承均值的理论。运行前用一句中文写下b中每一个元素代表什么，通常就能避免把自助样本与自助统计量混为一谈。'],
    'process-slices': ['把一张表画在纸上', '横轴写时间一、二、三，纵轴写实验甲、乙、丙，每个格子填对应读数。读一行是一条实际轨道，读一列是固定时刻跨实验的随机变量。接着圈出同一行两列的差，它是该轨道的一段增量。这样一张小表能解释大多数初学记号困难：下标告诉你读哪列，实验结果告诉你读哪行，而概率运算仍在纵向比较许多可能世界。'],
    'process-moments': ['用反向检查辨认漏掉的项', '把随机直线模型中的斜率方差暂时设为零，只剩随机起点时，所有时刻的中心化偏离都相同，协方差应是起点方差。把起点方差设为零，则协方差应是两个时刻各自乘斜率后的共同波动。再把两个方差都设为零，过程完全确定，协方差必须归零，未中心化乘积矩却未必为零。这三个简化情形能检查公式是否错把均值趋势当成随机波动，也提醒你同一条平均曲线可以配上很多不同协方差结构。'],
    'process-joint': ['不要让一张直方图替代联合关系', '你可以让甲模型在每次实验先抽一个标准正态数，之后所有时刻重复它；乙模型每时刻独立抽标准正态。每一刻画出的理论直方图完全相同，但甲的两个时刻必相等，乙几乎不可能精确相等。若只有逐刻均值与方差，就无法区分；补上协方差立即看见差别。这个练习强调统计描述的层级：单刻分布、二阶联系、完整联合规律，信息一层比一层多。'],
    'process-poisson': ['让单位替你检查公式', '若速率每小时二次，半小时参数应为一次；若改用分钟，速率变成每分钟三十分之一次，再乘三十分钟，仍得一次。指数等待的均值则是速率倒数，单位自然回到小时或分钟。公式里出现指数的量应当无单位，例如速率乘时间；若把每小时次数直接与分钟数相乘却未换算，错误往往会达到六十倍。对累计过程画阶梯，再标出你要计算的时间段，能同时检查单位和事件。'],
    'process-wiener': ['先用重叠长度判断相关', '拿两段增量分别在时间轴上涂色，它们没有重叠时，标准布朗独立增量给出独立；有重叠时，共同部分的扰动会同时进入两个增量。系数都为正时，共同部分使协方差等于重叠长度；若某段反向相减，符号也要跟着改变。把每个增量拆成互不重叠的小段后，只需加各段方差，不必背很长的四项展开。最后检查同一增量与自身的协方差应等于区间长度，这能发现漏号或时刻次序错误。'],
    'markov-state': ['从条件概率读出“忘记”的程度', '比较“已知今天在甲并且昨天在乙”与“只知今天在甲”的下一步概率，马尔可夫假设要求两者一致，前提是这些条件事件有正概率。它没有要求今天在甲与昨天在乙互相独立，也没有要求不同出发状态的下一步分布相同。如果所有行恰好一样，才会出现一个更特殊、对当前状态也不敏感的转移机制。把条件栏读完整，能防止把省略历史误解成消灭一切依赖。'],
    'markov-power': ['在小图上给每条两步路径贴标签', '先画两个圆甲、乙，从每个圆画出允许的一步箭头。指定从甲出发，分成第一步到甲和第一步到乙两支，再把两支各自延伸到第二步的两个终点。四条长度为二的路径互斥且覆盖全部可能，它们的概率总和应为一。把终点相同的路径放到同一盒子里求和，便得到矩阵平方第一行。这样你会清楚乘法来自沿同一条路线的条件概率，求和来自不同路线的互斥并集；矩阵只是把这棵小树整齐收起。三步时再加一层，含义完全不变。每一层都要保留所有允许的中间状态，不能只挑最可能的路线。'],
    'markov-balance': ['先理解质量，再理解特征向量', '线性代数会把平稳向量称为特征值一对应的左特征向量，但概率解释仍应放在前面：每个分量都是一份非负质量，所有分量必须总和一。一个符号解若含负数，就不具概率意义；一个任意倍数解还需归一化。某些状态平稳质量为零，也不表示它们从来不会在短期出现，它们可能只是最终流向闭类的暂态位置。先解释质量流向，再用线性代数求解，两种语言会互相补强。'],
    'markov-classes': ['把三个长期问题分开提问', '某个状态能否到达目标，问的是有无正概率路径；最终必然到达吗，问的是吸收或返性概率；大约要等多久，问的是到达时间的期望。存在一条路并不保证最终概率为一，更不保证平均等待很短。在有限具体模型中可以递推这些量，但递推方程的边界条件随目标改变。先画闭类能看出哪些地方会截留概率，再决定解哪一种方程，能避免拿一个“可达”结论回答所有等待问题。'],
    'markov-limits': ['先求误差界，再说“足够久”', '在两状态衰减例子里，从甲出发的概率误差是零点四乘二分之一的步数次方。若希望甲的概率与平稳值相差不超过百分之一，可以逐步检查：五步误差零点零一二五仍偏大，六步零点零零六二五已满足。这比只说时间很长更具体。另一个链即使有同样平稳分布，也可能每步只做极少切换，忘记起点会慢很多。平稳向量决定落点，转移机制还决定走向落点的速度；二者不能互相替代。报告近似程度时最好同时说明步数与允许误差。'],
    'stationary-types': ['把“相同”的层次逐个说出来', '你可以分别检查均值相同、方差相同、各时刻边缘分布相同、所有有限维联合分布在平移后相同。这几句话的强度不同，前一句通常不能推出后一句。做题最常见的漏步是均值恒定就停止；第二常见的是单时刻同分布便称严格平稳。把检查写成完整句子后，读者才知道你证明到了哪一层，自己也能看见哪些条件尚未使用。'],
    'stationary-phase': ['借转动钟面理解均匀相位', '把相位画成钟面上的一点，整圈均匀撒点后，把所有点旋转同一个角度，撒点的概率规则没有改变。时间平移正是在做这种共同旋转，因此整条轨迹的相对关系仍被保留。若相位只取两个固定角度，任意旋转后未必仍落在原来两个位置，不能照搬严格平稳证明。均值与协方差算式之外，完整的旋转不变性才是本模型更深的依据。它也说明随机性不一定每秒重新产生，开局抽一次仍可能让整个过程平稳。'],
    'stationary-ergodic': ['把长记录拆成几段只是诊断', '实际中可比较前、中、后三段的均值与相关图，若差异明显，应怀疑结构变化或记忆很长；若差异不明显，也不能据此证明各态历经。随机常数轨道的三段平均完全相同，却同样不代表总体均值。判断的核心不在一条记录内部看起来是否一致，而在模型允许的不同轨道之间是否存在永远无法靠时间探索的随机差异。这个反例能提醒你把经验诊断与理论保证分清。'],
    'stationary-covariance': ['把满相关翻译成几乎处处的等式', '如果两个中心化变量方差均为一且协方差为一，它们差的方差就是零，所以几乎处处相等；协方差为负一则几乎处处互为相反数。把这条等式沿三个时刻传递，就能很快识别互相矛盾的满相关标注。更一般的相关系数虽未达到边界，也仍要满足整体矩阵约束。你可以把半正定理解为所有这类潜在矛盾都被排除的一条统一条件，而不仅是一种需要按计算器的矩阵术语。先用等式反例建立直觉，再学矩阵检验，抽象名字就有了实际含义。'],
    'stationary-spectrum': ['先辨“峰高”与“面积”', '把同样一杯水倒进窄杯和宽盘，最高水位不同，总水量却相同。谱峰高度与总方差也有类似区别：窄频带可以堆出很高的峰，却未必有更大总方差。读谱图要看频轴单位、带宽和积分约定，不能只看纵轴最大值。若平均值尚未去掉，零频处的强成分还可能主要反映固定偏置，而非缓慢的随机波动。对照协方差零滞后值检查总面积，是让频域解释落回原数据单位的一座桥。'],
    'stationary-discrete-spectrum': ['采样频率改变，物理解释跟着改变', '同样一个离散频率峰，若每秒采一次和每小时采一次，对应的现实周期相差很大。不能只记录数组位置而丢掉时间戳。若观测不等间隔，直接套等间隔序列的离散频率解释也可能失效。做图时把采样间隔写在旁边，再问正负频率是否都包含、谱是单边还是双边；单边图经常把正负频率贡献合并，面积规则需要同步调整。把这些约定说清，比多画几个小数位更能避免误读。白噪声的“平”也须在同一约定内比较，不能忽略频轴单位。'],
    'timeseries-white': ['线性预测不等于所有可预测性', '如果过去的大小能预示未来波动的大小，却不能预示未来正负方向，原序列可能没有线性相关，平方序列却有相关。这正是乘积噪声例子展示的情况。残差诊断因此不应永远只看一张原残差自相关图；还可结合平方残差、业务背景与合适模型。反过来，有限样本中平方相关有一点突出，也不能立刻宣布发现确定规律。先区分总体性质、可检验线索和有限数据证据，才不会把任何一张图看成最终答案。'],
    'timeseries-ar': ['让一次冲击沿时间传播', '假设今天发生一次大小为四的冲击，之后暂时没有新冲击。系数二分之一会让它留下四、二、一、二分之一这样逐渐减弱的痕迹；系数负二分之一则正负交替而幅度同样衰减；系数一让四一直留在水平里。这个对照直接解释稳定、振荡和单位根的不同。真实路径还会不断叠加新冲击，不能把这条单冲击曲线当作每次实际轨道，但它能帮助你看懂模型如何传递记忆，以及为何接近单位根时长历史仍影响今天。'],
    'timeseries-maarma': ['用共享位置数出移动平均的相关', '把每个时刻的噪声编号写在纸上，再把相邻两个观测展开。相同编号才可能贡献协方差，不同编号因白噪声不相关而消失；同一编号前面的系数相乘，再乘噪声方差，最后求和。这个方法既适用于正权重，也适用于负权重。若两项相距超过移动平均阶数，没有任何共同编号，协方差就为零。它解释的是二阶截断而非完整独立，除非另外给独立噪声等条件。先把共享结构画出来，再用公式压缩，能避免把移动平均与自回归的记忆方式混淆。'],
    'timeseries-difference': ['差分不是删除时间顺序', '第一差分会少一个观测，差分值仍按时间排列，不能与原始水平错位。若训练结束于第八十天，第八十一天变化可使用已知的第八十天水平来还原，这不是泄漏；但不能用第八十二天真实水平帮助第八十一天预测。多步还原时，各步预测误差可能相关，区间计算必须尊重这种共同来源。把每个数标上它属于的日期和水平或差分身份，比只存一列没有标签的数字更能防止后续混乱。'],
    'timeseries-workflow': ['给最简单基线一个公平机会', '复杂模型应在同一预测时点、同一步长和同一误差指标下，与简单方法比较。如果只让复杂模型看到更长历史或采用不同测试日期，差异未必来自模型本身。基线表现强并不丢人，它说明这份数据中复杂结构尚未被可靠识别。保留每次预测时使用的数据范围、模型版本与预测值，日后才能复查评估是否偷看未来，也能观察环境改变后旧方法从何时开始失准。']
  };
  const symbolNotes = {
    'bootstrap-world': [{symbol:'Fₙ',read:'经验分布',meaning:'给每个原观测位置相同权重，作为重抽样的总体替身。',example:'样本2、4、6各占1/3。'},{symbol:'θ̂*',read:'西塔帽星',meaning:'对一份重抽样样本重新计算的估计值；星号不是乘法。',example:'一份星号样本2、2、6的均值是10/3。'}],
    'process-slices': [{symbol:'X(t,ω)',read:'时间t、实验结果欧米伽对应的读数',meaning:'固定t得到随机变量，固定ω得到一条轨迹。',example:'N(5,某一天)是那天第五分钟的累计人数。'}],
    'process-moments': [{symbol:'m(t)',read:'时刻t的均值函数',meaning:'固定时刻跨实验取期望。',example:'随机直线例子中m(t)=1+2t。'},{symbol:'C(s,t)',read:'两个时刻的协方差',meaning:'先各自减均值，再看乘积的平均。',example:'随机直线例子中C(s,t)=4+st。'},{symbol:'R(s,t)',read:'未中心化相关函数',meaning:'本课取E[X(s)X(t)]，不自动等于协方差。',example:'R(s,t)=C(s,t)+m(s)m(t)。'}],
    'markov-state': [{symbol:'Pᵢⱼ',read:'从状态i一步到状态j的概率',meaning:'本课行是起点，列是终点。',example:'第一行第二列0.2表示A→B概率0.2。'}],
    'markov-balance': [{symbol:'π=πP',read:'平稳分布乘转移矩阵仍是自己',meaning:'π是非负、和为1的行向量，描述概率质量平衡。',example:'(0.6,0.4)P=(0.6,0.4)。'}],
    'stationary-covariance': [{symbol:'τ',read:'陶，时间差',meaning:'宽平稳时协方差只取决于两时刻相隔多久。',example:'τ=t−s，不是绝对时刻t。'},{symbol:'ρ(τ)',read:'标准化自相关系数',meaning:'C(0)>0时，取C(τ)/C(0)，没有单位。',example:'ρ(0)=1。'}],
    'stationary-spectrum': [{symbol:'ω',read:'欧米伽，角频率',meaning:'每单位时间多少弧度，与周期频率f关系为ω=2πf。',example:'ω=2π时，每单位时间完成一个周期。'}],
    'timeseries-ar': [{symbol:'εₜ',read:'时刻t新增的扰动',meaning:'零均值、恒方差的噪声；是否独立还需题设。',example:'Yₜ=0.5Yₜ₋₁+εₜ。'},{symbol:'φ',read:'菲，自回归系数',meaning:'控制过去偏离在下一时刻留下的比例与符号。',example:'φ=−0.5意味着反向且减半。'}],
    'timeseries-maarma': [{symbol:'B',read:'后移算子',meaning:'把序列位置向前移一格，是操作而不是普通数值。',example:'BXₜ=Xₜ₋₁。'}],
    'timeseries-difference': [{symbol:'ΔXₜ',read:'时刻t的一阶差分',meaning:'本期水平减上一期水平，描述本期变化量。',example:'100变为103，一阶差分为3。'}]
  };
  let quizIndex = 0;
  for (const chapter of chapters) for (const lesson of chapter.lessons) {
    const note = readingNotes[lesson.id.slice(5)];
    if (note) lesson.sections.push(S(note[0], note[1]));
    const symbols = symbolNotes[lesson.id.slice(5)];
    if (symbols) lesson.symbols = symbols;
    const shift = [1, 3, 0, 2][quizIndex++ % 4];
    const shuffled = Array(4);
    lesson.quiz.options.forEach((option, i) => { shuffled[(i + shift) % 4] = option; });
    lesson.quiz.options = shuffled;
    lesson.quiz.answer = (lesson.quiz.answer + shift) % 4;
  }
  (window.PROB_CHAPTERS ||= []).push(...chapters.sort((a, b) => a.order - b.order));
})();
